module SeedCurriculum
  def self.question(prompt, options, correct_option, explanation)
    {
      question: prompt,
      option_a: options[0],
      option_b: options[1],
      option_c: options[2],
      option_d: options[3],
      correct_option: correct_option,
      explanation: explanation
    }
  end

  def self.module_data(title, summary, concept, example, prompt, options, correct_option, explanation, practice, level: nil)
    {
      title: title,
      summary: summary,
      concept: concept,
      example: example,
      question: prompt,
      option_a: options[0],
      option_b: options[1],
      option_c: options[2],
      option_d: options[3],
      correct_option: correct_option,
      explanation: explanation,
      difficulty_level: level,
      quiz_questions: practice.map { |item| question(*item) }
    }
  end

  def self.track(name, slug, icon, color, description, lessons)
    {
      name: name,
      slug: slug,
      icon: icon,
      color: color,
      description: description,
      lessons: lessons
    }
  end

