        [ "Por que se balanceia a equação antes de calcular uma titulação?", [ "Para conhecer a proporção molar entre analito e titulante.", "Para escolher a cor do frasco.", "Para descobrir a massa do indicador.", "Para dispensar a concentração do titulante." ], "a", "Os coeficientes da equação balanceada determinam a relação entre os mols que reagem." ],
        [ "Um indicador ácido-base muda de cor porque:", [ "Suas formas protonada e desprotonada têm cores diferentes.", "A solução fica necessariamente saturada.", "O titulante muda de massa molar.", "A bureta aquece a amostra." ], "a", "O equilíbrio do indicador muda com o pH e altera a proporção entre as formas coloridas." ],
        [ "Para escolher um indicador, sua faixa de transição deve:", [ "Ficar próxima da região de variação acentuada do pH na equivalência.", "Estar sempre em pH 7.", "Ficar muito distante da equivalência.", "Ser igual à concentração do analito." ], "a", "A transição precisa ocorrer onde uma pequena adição de titulante provoca mudança de pH detectável." ],
        [ "A titulação de ácido fraco com base forte apresenta, antes da equivalência:", [ "Uma região tampão formada pelo ácido e sua base conjugada.", "Somente ácido forte.", "pH sempre igual a 7.", "Ausência de reação." ], "a", "A neutralização parcial produz ácido fraco e base conjugada, que formam um tampão." ],
        [ "No ponto de equivalência de ácido fraco com base forte, o pH tende a ser:", [ "Menor que 7 em qualquer temperatura.", "Maior que 7, devido à hidrólise da base conjugada.", "Sempre exatamente 7.", "Igual a zero." ], "b", "A base conjugada formada pode reagir com água e gerar OH⁻." ],
        [ "Se o ponto final é observado depois da equivalência, o volume anotado tende a:", [ "Ser maior que o volume estequiométrico.", "Ser menor sempre.", "Ser igual a zero.", "Não depender do indicador." ], "a", "A mudança tardia faz adicionar titulante em excesso antes de interromper a titulação." ],
        [ "Uma curva de titulação relaciona:", [ "pH e volume de titulante adicionado.", "Massa do béquer e cor do indicador.", "Pressão e número atômico.", "Temperatura e massa molar apenas." ], "a", "A curva mostra como o pH varia à medida que o titulante é adicionado." ],
        [ "Por que um indicador inadequado pode gerar erro?", [ "Sua mudança de cor pode ocorrer longe da equivalência.", "Ele altera os coeficientes balanceados.", "Ele substitui a amostra.", "Ele faz a bureta perder volume." ], "a", "Uma faixa de transição distante do salto de pH desloca o ponto final observado." ]
