    track("Química Orgânica II", "quimica-organica-ii", "O2", "#efd8b7",
      "Avance em isomeria, reações e aplicações de compostos orgânicos.",
      [
        module_data("Isomeria e estrutura molecular", "Descubra como fórmulas iguais podem representar substâncias diferentes.",
          "Isômeros são compostos que têm a mesma fórmula molecular, mas diferem na maneira como os átomos estão conectados ou organizados no espaço. Na isomeria constitucional, muda a conectividade: a cadeia pode ser ramificada de modos diferentes ou o grupo funcional pode mudar. Na estereoisomeria, a conectividade é igual, mas a disposição espacial difere.\n\nPara identificar isômeros, conte primeiro os átomos e confira a fórmula; em seguida, compare as ligações e a orientação espacial. Isomeria não é apenas uma diferença no desenho: estruturas diferentes podem ter pontos de ebulição, solubilidade, cheiro ou atividade biológica distintos.\n\nA rotação em torno de uma ligação simples costuma ser possível, mas uma ligação dupla restringe a rotação e pode gerar formas cis/trans ou E/Z quando os substituintes permitem. A presença de um carbono ligado a quatro grupos diferentes pode gerar enantiômeros, imagens especulares não sobreponíveis. Esses conceitos se tornam especialmente importantes em medicamentos e moléculas biológicas.",
          "Butano e 2-metilpropano têm fórmula C₄H₁₀, porém um apresenta cadeia linear e o outro ramificada: são isômeros constitucionais. A contagem de átomos confirma a fórmula comum; a conectividade mostra por que são moléculas diferentes.",
          "Butano e 2-metilpropano, ambos C₄H₁₀, diferem principalmente por:", [ "Número de prótons.", "Conectividade da cadeia carbônica.", "Composição elementar.", "Carga elétrica total." ], "b",
          "Ambos têm a mesma fórmula, mas diferem no esqueleto carbônico e são isômeros de cadeia.",
          [
            [ "Etanol e metoximetano têm fórmula C₂H₆O e grupos diferentes. Esse caso é:", [ "Isomeria de cadeia.", "Isomeria de função.", "Isotopia.", "Alotropia." ], "b", "Etanol é álcool e metoximetano é éter; possuem a mesma fórmula molecular e funções diferentes." ],
            [ "Qual par pode apresentar isomeria geométrica cis/trans?", [ "Etano.", "But-2-eno.", "Metano.", "Etino." ], "b", "A ligação dupla do but-2-eno restringe a rotação e cada carbono da dupla tem dois substituintes diferentes." ],
            [ "Quantos isômeros constitucionais acíclicos tem C₄H₁₀?", [ "Um.", "Dois.", "Três.", "Quatro." ], "b", "Há butano de cadeia normal e 2-metilpropano." ],
            [ "Enantiômeros são:", [ "Moléculas com fórmulas diferentes.", "Imagens especulares não sobreponíveis.", "A mesma substância em estados físicos diferentes.", "Íons com cargas opostas." ], "b", "Enantiômeros são pares de estereoisômeros que são imagens especulares não sobreponíveis." ],
            [ "Um carbono quiral tetraédrico está ligado a:", [ "Quatro grupos iguais.", "Quatro grupos diferentes.", "Duas ligações duplas.", "Nenhum hidrogênio em qualquer caso." ], "b", "Quatro substituintes diferentes tornam o carbono um centro estereogênico comum." ],
            [ "Por que há isomeria cis/trans em certas ligações duplas?", [ "Porque a rotação em torno de C=C é livre.", "Porque a rotação é restringida pela ligação pi.", "Porque as moléculas não têm carbono.", "Porque os átomos ionizam." ], "b", "A ligação pi impede rotação livre e preserva arranjos espaciais distintos." ],
            [ "Isômeros de cadeia diferem em:", [ "Conectividade do esqueleto de carbonos.", "Número atômico do carbono.", "Carga nuclear.", "Quantidade de prótons." ], "a", "A cadeia pode ser linear ou ramificada mantendo a mesma fórmula molecular." ],
            [ "A fórmula molecular C₃H₆O pode representar mais de uma função. O que permite distingui-las?", [ "Apenas a massa da amostra.", "A fórmula estrutural e a conectividade dos átomos.", "A cor do frasco.", "A temperatura ambiente." ], "b", "A fórmula molecular não identifica sozinha a conectividade nem o grupo funcional." ],
            [ "Dois isômeros podem ter propriedades físicas diferentes porque:", [ "A estrutura e as interações intermoleculares podem diferir.", "Um deles necessariamente tem outro número de prótons.", "Isômeros nunca são compostos orgânicos.", "A fórmula molecular muda durante a comparação." ], "a", "A geometria e a conectividade afetam interações e propriedades físicas." ]
