    track("Química I", "quimica-i", "Q1", "#d9e8d2",
      "Fundamentos de matéria, estrutura atômica, ligações e quantidades químicas.",
      [
        module_data("Estrutura da matéria e ligações químicas", "Comece pelos átomos e entenda como eles formam substâncias.",
          "A matéria é composta por átomos, que contêm prótons e nêutrons no núcleo e elétrons ao redor. Elementos são identificados pelo número de prótons; compostos reúnem elementos em proporções definidas. Uma fórmula química representa quais átomos participam e quantos aparecem na menor unidade ou molécula.\n\nÁtomos podem se unir por ligações. Na ligação iônica, há atração entre íons de cargas opostas, geralmente após transferência de elétrons. Na covalente, átomos compartilham pares de elétrons. Na metálica, elétrons deslocalizados ajudam a explicar condutividade e maleabilidade dos metais. Esses modelos são ferramentas para explicar propriedades, não desenhos literais de partículas.\n\nAs propriedades macroscópicas dependem do tipo de partículas e das interações entre elas. Um sólido iônico pode conduzir eletricidade quando fundido ou dissolvido, pois os íons ficam móveis; no estado sólido, costumam estar presos em posições da rede. Relacionar estrutura e propriedade permite prever comportamentos simples.",
          "No NaCl sólido, Na⁺ e Cl⁻ estão organizados em uma rede iônica. No sal dissolvido, os íons se separam e podem transportar carga em solução; por isso, uma solução aquosa de NaCl conduz corrente elétrica.",
          "Por que uma solução aquosa de NaCl conduz eletricidade?", [ "Porque moléculas de água viram metais.", "Porque há íons móveis que transportam carga.", "Porque o sal não se dissolve.", "Porque prótons saem dos núcleos." ], "b",
          "Íons Na⁺ e Cl⁻ hidratados podem se deslocar e transportar carga elétrica.",
          [
            [ "Qual partícula define o número atômico de um elemento?", [ "Nêutron.", "Próton.", "Molécula.", "Fóton." ], "b", "O número de prótons é o número atômico." ],
            [ "Uma ligação covalente é caracterizada principalmente por:", [ "Compartilhamento de pares de elétrons.", "Transferência de prótons do núcleo.", "Ausência de elétrons.", "Atração gravitacional entre átomos." ], "a", "Átomos compartilham pares de elétrons em ligações covalentes." ],
            [ "Um átomo neutro de Z=8 tem quantos elétrons?", [ "6.", "8.", "16.", "0." ], "b", "Um átomo neutro tem igual quantidade de prótons e elétrons." ],
            [ "Qual fórmula representa um composto iônico neutro de Mg²⁺ e Cl⁻?", [ "MgCl.", "MgCl₂.", "Mg₂Cl.", "Mg₂Cl₃." ], "b", "Dois cloretos de carga −1 neutralizam um magnésio de carga +2." ],
            [ "Em geral, um cátion se forma quando o átomo:", [ "Ganha elétrons.", "Perde elétrons.", "Ganha nêutrons.", "Perde prótons." ], "b", "Perder elétrons deixa carga positiva líquida." ],
            [ "Qual característica é comum em metais?", [ "Boa condução elétrica no estado sólido.", "Ausência de elétrons móveis.", "Fragilidade de todos os sólidos.", "Formação exclusiva de gases." ], "a", "Elétrons deslocalizados contribuem para a condução em metais." ],
            [ "O coeficiente 2 em 2H₂O indica:", [ "Dois átomos de oxigênio no total.", "Duas moléculas ou unidades de água.", "Dois elementos diferentes.", "Duas cargas positivas." ], "b", "Coeficiente multiplica toda a fórmula e conta unidades de substância." ],
            [ "Qual lei exige o mesmo número de átomos de cada elemento nos dois lados da equação?", [ "Conservação da massa.", "Lei da gravitação.", "Lei de Ohm.", "Lei da refração." ], "a", "Em reações químicas, os átomos são reorganizados, não criados nem destruídos." ],
            [ "Qual substância simples é formada por um único elemento químico?", [ "H₂O.", "CO₂.", "O₂.", "NaCl." ], "c", "O₂ contém apenas átomos do elemento oxigênio." ]
          ]),
        module_data("Mol, massa molar e estequiometria", "Transforme massas em quantidades químicas e calcule proporções de reação.",
          "O mol é a unidade SI de quantidade de matéria e corresponde a um número definido de entidades elementares. Em cálculos do cotidiano, a massa molar M, em g/mol, conecta a massa m à quantidade n: n=m/M. Para uma solução, a concentração molar c relaciona mols ao volume final em litros: c=n/V.\n\nUma equação química balanceada informa proporções entre partículas ou mols, não entre massas diretamente. Primeiro balanceie os átomos; depois use os coeficientes como razões molares. Converta unidades antes de substituir valores e verifique se a resposta faz sentido.\n\nEm um problema estequiométrico com dois reagentes, compare as quantidades disponíveis com a proporção da equação para identificar o reagente limitante. Ele determina a quantidade máxima de produto. O reagente em excesso permanece parcialmente sem reagir. Rendimento percentual compara a quantidade real obtida com a quantidade teórica prevista.",
          "Na reação 2H₂ + O₂ → 2H₂O, 2 mol de H₂ reagem com 1 mol de O₂. Se há 4 mol de H₂ e 1 mol de O₂, o oxigênio limita a reação e forma no máximo 2 mol de água.",
          "Na reação 2H₂ + O₂ → 2H₂O, qual quantidade de água pode ser formada a partir de 3 mol de O₂ com H₂ em excesso?", [ "1 mol.", "2 mol.", "3 mol.", "6 mol." ], "d",
          "A razão O₂:H₂O é 1:2; 3 mol de O₂ podem formar 6 mol de H₂O.",
