            [ "Uma solução contém 0,50 mol em 2,0 L. Qual é a molaridade?", [ "0,25 mol/L.", "1,0 mol/L.", "2,5 mol/L.", "4,0 mol/L." ], "a", "c=n/V=0,50/2,0=0,25 mol/L." ],
            [ "Na equação N₂+3H₂→2NH₃, quantos mols de H₂ reagem com 2 mol de N₂?", [ "2 mol.", "3 mol.", "6 mol.", "9 mol." ], "c", "A proporção de coeficientes N₂:H₂ é 1:3; 2 mol N₂ exigem 6 mol H₂." ],
            [ "O reagente limitante é aquele que:", [ "Está em maior massa sempre.", "Se esgota primeiro segundo a proporção da reação.", "Tem maior massa molar.", "Nunca participa do produto." ], "b", "O reagente limitante controla a quantidade teórica máxima de produto." ],
            [ "Qual massa corresponde a 0,25 mol de NaCl? Use M=58,5 g/mol.", [ "0,0146 g.", "14,6 g.", "58,5 g.", "234 g." ], "b", "m=nM=0,25×58,5=14,625 g, aproximadamente 14,6 g." ],
            [ "Uma reação prevê 10 g de produto, mas são obtidos 8 g. Qual é o rendimento percentual?", [ "20%.", "80%.", "100%.", "125%." ], "b", "Rendimento=8/10×100=80%." ],
            [ "Por que se balanceia uma equação antes do cálculo estequiométrico?", [ "Para obter proporções molares corretas e conservar átomos.", "Para aumentar a massa do produto.", "Para remover o reagente limitante.", "Para mudar as fórmulas das substâncias." ], "a", "Coeficientes balanceados expressam a proporção correta entre as espécies." ],
            [ "Ao calcular c=n/V em mol/L, o volume deve ser expresso em:", [ "Litros.", "Gramas.", "Mol.", "Graus Celsius." ], "a", "A unidade mol/L requer que V esteja em litros." ],
            [ "Qual é a massa molar de CO₂? Use C=12 e O=16 g/mol.", [ "28 g/mol.", "32 g/mol.", "44 g/mol.", "48 g/mol." ], "c", "M(CO₂)=12+2×16=44 g/mol." ]
          ])
      ]),
    track("Química II", "quimica-ii", "Q2", "#d3e2e8",
      "Aprofunde soluções, equilíbrio, ácidos e bases e transformações energéticas.",
      [
        module_data("Soluções, concentração e propriedades", "Interprete solubilidade, unidades de concentração e diluição.",
          "Uma solução é uma mistura homogênea com soluto dissolvido em solvente. Solubilidade expressa quanto soluto pode dissolver-se em certas condições; temperatura e, para gases, pressão podem alterar esse limite. Uma solução insaturada ainda pode dissolver mais soluto, uma saturada está no limite nas condições dadas e uma supersaturada é instável e contém mais soluto dissolvido que o equilíbrio usual.\n\nConcentração quantifica a composição. Molaridade é mol de soluto por litro de solução; concentração em massa pode ser expressa em g/L; porcentagens precisam especificar a base (m/m, m/v ou v/v). Ao diluir sem reação ou perda, os mols transferidos permanecem constantes e c₁V₁=c₂V₂.\n\nPrepare soluções considerando o volume final, não apenas o volume de solvente. Ao dissolver um sólido, pese a quantidade calculada, dissolva em parte do solvente, transfira quantitativamente e complete em material volumétrico adequado. Indique sempre unidades e condições para que o resultado seja compreensível.",
          "Para preparar 100 mL de 0,20 mol/L a partir de estoque 1,0 mol/L, c₁V₁=c₂V₂; V₁=(0,20×100)/1,0=20 mL. Transfira 20 mL do estoque e complete o volume final até 100 mL.",
