            [ "O que acontece com a concentração ao adicionar solvente sem perder soluto?", [ "Aumenta.", "Diminui.", "Permanece sempre idêntica.", "A massa molar muda." ], "b", "A quantidade de soluto permanece e o volume aumenta, reduzindo a concentração." ],
            [ "Uma solução 5% (m/v) contém:", [ "5 g por 100 mL de solução.", "5 g por 100 g de solução.", "5 mol por litro.", "5 mL por 100 g de solvente." ], "a", "% m/v é gramas de soluto em cada 100 mL de solução." ],
            [ "Qual fator costuma aumentar a solubilidade de um sólido em líquido?", [ "Aumentar a temperatura em muitos casos, embora dependa do sistema.", "Diminuir sempre a pressão.", "Remover o solvente.", "Adicionar um filtro." ], "a", "Muitos sólidos têm solubilidade maior em temperaturas elevadas; a tendência deve ser verificada para cada substância." ],
            [ "Uma solução está saturada quando:", [ "Todo soluto virou gás.", "Contém a quantidade máxima dissolvida em equilíbrio nas condições especificadas.", "Não contém solvente.", "Sua concentração é sempre 1 mol/L." ], "b", "Saturação depende da solubilidade na temperatura, pressão e composição dadas." ],
            [ "Em 2,0 L de solução 0,25 mol/L, quantos mols de soluto existem?", [ "0,125 mol.", "0,50 mol.", "2,25 mol.", "8,0 mol." ], "b", "n=cV=0,25×2,0=0,50 mol." ],
            [ "Por que se usa o volume final da solução na molaridade?", [ "Porque molaridade é mol de soluto por volume total da solução.", "Porque só o solvente pode ser medido.", "Porque o soluto não ocupa volume.", "Porque a massa não conserva." ], "a", "A definição usa volume da solução pronta, não somente o solvente adicionado." ],
            [ "Uma solução 2,0 mol/L é diluída de 50 mL para 200 mL. Qual concentração final?", [ "0,50 mol/L.", "1,0 mol/L.", "2,0 mol/L.", "8,0 mol/L." ], "a", "c₂=c₁V₁/V₂=2,0×50/200=0,50 mol/L." ],
            [ "Uma solução supersaturada é geralmente:", [ "Mais estável que uma solução saturada em qualquer condição.", "Metaestável e pode cristalizar após perturbação.", "Uma mistura heterogênea obrigatoriamente.", "Uma solução sem soluto." ], "b", "Ela pode conter excesso dissolvido e cristalizar quando nucleação é iniciada." ]
          ]),
        module_data("Equilíbrio químico, ácidos e bases", "Compreenda reações reversíveis, pH e previsões qualitativas de equilíbrio.",
          "Algumas reações são reversíveis: reagentes formam produtos e produtos também podem voltar a formar reagentes. No equilíbrio dinâmico, as velocidades direta e inversa são iguais, embora as concentrações macroscópicas permaneçam constantes. Isso não significa que as quantidades de reagentes e produtos sejam iguais.\n\nA constante de equilíbrio K relaciona concentrações ou pressões parciais no equilíbrio, elevadas aos coeficientes estequiométricos. Para uma temperatura definida, K não muda quando se adiciona reagente; o sistema se ajusta e o quociente reacional muda. Alterar a temperatura pode mudar K. Pelo princípio de Le Châtelier, o equilíbrio tende a responder a uma perturbação reduzindo seu efeito: por exemplo, aumentar a pressão favorece o lado com menos mols gasosos, quando aplicável.\n\nÁcidos doam prótons e bases os recebem no modelo de Brønsted−Lowry. Em água diluída, pH=-log[H₃O⁺] e pOH=-log[OH⁻]. Ácidos e bases fracos ionizam parcialmente; suas constantes de equilíbrio descrevem essa extensão. Em neutralizações, use a equação balanceada e as quantidades de matéria antes de inferir pH ou excesso.",
          "No equilíbrio N₂(g)+3H₂(g) ⇌ 2NH₃(g), há quatro mols gasosos à esquerda e dois à direita. Aumentar a pressão, mantendo temperatura, favorece o lado com menos mols de gás, deslocando o sistema para NH₃; K permanece constante se a temperatura não mudar.",
          "Para N₂(g)+3H₂(g) ⇌ 2NH₃(g), o aumento de pressão a temperatura constante tende a favorecer:", [ "N₂ e H₂.", "NH₃.", "Ambos igualmente em qualquer condição.", "A decomposição da água." ], "b",
          "O lado dos produtos tem menos mols gasosos e é favorecido pelo aumento da pressão.",
          [
            [ "No equilíbrio dinâmico:", [ "As velocidades direta e inversa são iguais.", "As reações param completamente.", "As concentrações precisam ser iguais.", "Só existe produto." ], "a", "As transformações continuam ocorrendo em velocidades iguais, mantendo concentrações constantes." ],
            [ "Para uma reação definida, a constante K depende diretamente de:", [ "Temperatura.", "Quantidade inicial de produto apenas.", "Cor do recipiente.", "Massa do catalisador." ], "a", "A constante de equilíbrio muda com temperatura, não com catalisador ou concentrações iniciais." ],
            [ "Uma solução com [H₃O⁺]=10⁻⁴ mol/L tem pH aproximado:", [ "4.", "7.", "10.", "14." ], "a", "pH=−log(10⁻⁴)=4." ],
            [ "Um ácido fraco em água:", [ "Ioniza completamente.", "Estabelece equilíbrio de ionização parcial.", "Não doa prótons.", "Sempre tem pH 7." ], "b", "Ácido fraco ioniza parcialmente e sua composição é descrita por equilíbrio." ],
            [ "Um catalisador adicionado a um sistema em equilíbrio:", [ "Muda K.", "Acelera a chegada ao equilíbrio sem alterar sua composição final.", "Desloca sempre para produtos.", "Consome todo o reagente." ], "b", "Catalisador acelera as duas direções, sem alterar K ou a posição de equilíbrio." ],
            [ "Se produtos são removidos de um equilíbrio, a resposta usual é:", [ "Formar mais produtos.", "Parar toda reação.", "Aumentar K sem mudar temperatura.", "Destruir os catalisadores." ], "a", "A remoção de produto favorece a direção direta para repor parte do que foi removido." ],
            [ "Qual espécie é uma base de Brønsted−Lowry?", [ "Doadora de próton.", "Aceptora de próton.", "Sempre um metal.", "Sempre libera nêutrons." ], "b", "Base de Brønsted−Lowry recebe próton." ],
            [ "Se pOH=3 a 25 °C, qual é [OH⁻]?", [ "10⁻³ mol/L.", "3 mol/L.", "10³ mol/L.", "10⁻¹¹ mol/L." ], "a", "pOH=−log[OH⁻], então [OH⁻]=10⁻³ mol/L." ],
            [ "Na expressão de K, os expoentes das concentrações correspondem:", [ "Aos coeficientes estequiométricos balanceados.", "Aos números atômicos.", "Às massas molares.", "À temperatura em °C." ], "a", "Coeficientes da equação balanceada tornam-se expoentes na expressão de equilíbrio." ]
          ])
      ]),
    track("Análise Instrumental", "analise-instrumental", "AI", "#cbdfe8",
      "Aprenda os princípios de cromatografia, eletroanalítica e técnicas espectroanalíticas.",
      [
        module_data("Fundamentos de análise instrumental", "Entenda sinal, calibração, seletividade e limites de medição.",
          "Uma técnica instrumental transforma uma propriedade da amostra em um sinal mensurável. O sinal pode depender da quantidade do analito, mas também de ruído, condições do equipamento e componentes da matriz. Por isso, identificar um sinal não basta: é necessário demonstrar que ele responde ao analito e convertê-lo em resultado por um procedimento apropriado.\n\nCalibração relaciona respostas do instrumento a padrões de concentração conhecida. Em uma curva, mede-se o sinal dos padrões e estima-se a concentração da amostra dentro da faixa validada. Um branco ajuda a avaliar sinal de fundo; réplicas mostram repetibilidade; materiais de referência e ensaios de recuperação ajudam a avaliar viés. Limite de detecção e limite de quantificação descrevem capacidades distintas: detectar não significa necessariamente quantificar com precisão adequada.\n\nSeletividade é a capacidade de distinguir o analito de outras espécies. Sensibilidade descreve quanto o sinal varia com a concentração. Precisão trata da proximidade entre resultados repetidos; exatidão, da proximidade ao valor de referência. A escolha de técnica depende da pergunta, faixa de concentração, matriz, preparo, custo, tempo e segurança.",
          "Uma curva preparada com padrões fornece sinal S=2,0C+0,1. Se a amostra apresenta S=1,1 dentro da faixa calibrada, estima-se C=(1,1−0,1)/2,0=0,50 na unidade de concentração usada para os padrões. A conversão só é válida se branco, matriz e faixa forem adequados.",
          "O que permite transformar o sinal instrumental em concentração?", [ "Uma curva de calibração com padrões apropriados.", "A cor do equipamento.", "A massa do frasco vazio.", "Uma leitura isolada sem comparação." ], "a",
          "A calibração relaciona respostas medidas a concentrações conhecidas dentro de uma faixa válida.",
          [
            [ "Um branco analítico serve principalmente para:", [ "Medir somente a amostra.", "Avaliar sinal de fundo e possíveis contaminações do procedimento.", "Substituir todos os padrões.", "Aumentar a concentração do analito." ], "b", "O branco permite identificar sinal que não vem do analito da amostra." ],
            [ "Precisão descreve principalmente:", [ "Proximidade entre resultados replicados.", "Proximidade ao valor verdadeiro apenas.", "Ausência de unidade.", "Sensibilidade do detector." ], "a", "Precisão refere-se à concordância entre medições repetidas." ],
            [ "Um sinal acima do limite de detecção garante uma quantificação confiável?", [ "Sim, sempre.", "Não; pode estar abaixo do limite de quantificação.", "Sim, se o frasco for transparente.", "Não, porque instrumentos não medem sinais." ], "b", "Detecção e quantificação têm critérios distintos de desempenho." ],
            [ "A matriz da amostra pode:", [ "Alterar ou interferir no sinal do analito.", "Mudar o número atômico do analito.", "Eliminar a necessidade de calibração.", "Garantir seletividade." ], "a", "Componentes da matriz podem aumentar, reduzir ou sobrepor o sinal analítico." ],
            [ "Um padrão analítico deve ter:", [ "Concentração conhecida e preparo confiável.", "Identidade desconhecida.", "Sempre cor idêntica à amostra.", "Volume não registrado." ], "a", "Padrões com valor conhecido permitem construir calibração e avaliar o método." ],
            [ "Se os padrões cobrem 1 a 10 mg/L, quantificar uma amostra de 50 mg/L por extrapolação é:", [ "Sempre confiável.", "Arriscado; deve-se diluir ou ampliar e validar a faixa.", "Igual a medir dentro da faixa.", "Uma forma de corrigir interferências." ], "b", "Extrapolar muito além dos padrões pode produzir resultado não validado; diluição apropriada é comum." ],
            [ "A seletividade de um método refere-se à capacidade de:", [ "Distinguir o analito de componentes interferentes.", "Medir grande volume.", "Aumentar a temperatura.", "Repetir a análise sem variação." ], "a", "Seletividade trata da distinção do analito diante de outras espécies." ],
            [ "Qual controle ajuda a avaliar recuperação do analito na matriz?", [ "Adicionar quantidade conhecida do analito e medir o aumento recuperado.", "Retirar todos os padrões.", "Medir apenas o frasco vazio.", "Aumentar a resolução da tela." ], "a", "Adição conhecida permite comparar quantidade adicionada com incremento encontrado." ],
            [ "Se resultados replicados são muito próximos, mas distantes do padrão certificado, o método pode ser:", [ "Preciso, mas com viés.", "Exato e sem precisão.", "Livre de interferência.", "Não calibrado por definição." ], "a", "Baixa dispersão indica precisão; desvio do padrão sugere viés." ]
          ]),
        module_data("Cromatografia, eletroanalítica e espectroanalítica", "Compare técnicas instrumentais e escolha a medição de acordo com a propriedade do analito.",
          "Na cromatografia, os componentes de uma mistura distribuem-se de maneira diferente entre uma fase estacionária e uma fase móvel. Essa diferença de interação faz cada componente percorrer o sistema em tempos distintos. Cromatografia pode separar, identificar por comparação com padrões e quantificar por sinal calibrado; tempo de retenção sozinho não confirma identidade sem controles.\n\nTécnicas eletroanalíticas medem propriedades elétricas relacionadas à composição, como potencial, corrente ou carga. Potenciometria, por exemplo, mede diferença de potencial com corrente muito pequena e pode ser usada para pH com eletrodo apropriado. A resposta depende de calibração, temperatura, estado do eletrodo e interferentes.\n\nTécnicas espectroanalíticas investigam a interação entre matéria e radiação. Em espectrofotometria de absorção, mede-se quanto da luz é absorvida em determinados comprimentos de onda. Uma curva de calibração relaciona absorvância à concentração dentro de condições e faixa adequadas. Cada técnica possui vantagens, limitações, preparo e interferências próprios.",
          "Para uma solução colorida que absorve luz, mede-se a absorvância em comprimento de onda apropriado e compara-se a resposta com padrões. Para separar vários componentes de uma amostra complexa, a cromatografia pode ser mais indicada; para estimar atividade de H⁺, usa-se potenciometria com eletrodo de pH calibrado.",
          "Qual técnica é indicada para separar componentes de uma mistura pela diferença de interação com duas fases?", [ "Cromatografia.", "Pesagem direta.", "Filtração de gás.", "Calorimetria apenas." ], "a",
          "A separação cromatográfica depende da distribuição dos componentes entre fases móvel e estacionária.",
          [
            [ "Na cromatografia, um componente que interage mais fortemente com a fase estacionária tende a:", [ "Ser retido por mais tempo, em condições comparáveis.", "Sair sempre primeiro.", "Deixar de ser detectável.", "Transformar-se em solvente." ], "a", "Maior interação com a fase estacionária costuma aumentar a retenção." ],
            [ "A fase móvel em cromatografia é:", [ "A fase que se desloca pelo sistema carregando os componentes.", "O detector.", "O padrão certificado.", "Apenas o suporte externo." ], "a", "A fase móvel transporta os analitos através da fase estacionária." ],
            [ "Um eletrodo de pH mede principalmente:", [ "Diferença de potencial relacionada à atividade de H⁺.", "Massa do ácido.", "Volume de base.", "Absorção de calor." ], "a", "O instrumento potenciométrico relaciona potencial do eletrodo à atividade de H⁺." ],
            [ "Por que calibrar um medidor de pH com soluções tampão?", [ "Para relacionar potencial medido a valores de pH conhecidos.", "Para aumentar a massa da amostra.", "Para remover água.", "Para produzir ácido na amostra." ], "a", "Tampões conhecidos permitem ajustar e verificar a resposta do eletrodo." ],
            [ "A espectrofotometria de absorção mede:", [ "A diminuição de intensidade de luz após atravessar a amostra.", "A massa do analito no prato.", "A velocidade do agitador.", "Somente a temperatura do solvente." ], "a", "A técnica compara a radiação incidente e transmitida ou absorvida." ],
            [ "A lei de Beer-Lambert relaciona, em certas condições, absorvância a:", [ "Concentração e caminho óptico.", "Massa molar e pressão apenas.", "Velocidade de rotação.", "Ponto de fusão." ], "a", "A = εbc, com absortividade, caminho óptico e concentração, dentro do regime aplicável." ],
            [ "Para confirmar um pico cromatográfico suspeito, é melhor:", [ "Comparar com padrão e usar controles ou evidências adicionais.", "Assumir identidade apenas pelo tamanho do pico.", "Ignorar o método de separação.", "Mudar a unidade da concentração." ], "a", "Tempo de retenção pode apoiar identificação, mas padrão e evidências complementares fortalecem a conclusão." ],
            [ "Uma amostra dá absorvância acima da faixa linear validada. Qual ação é adequada?", [ "Diluir a amostra adequadamente e medir novamente.", "Extrapolar sem verificar.", "Zerar o detector com a amostra.", "Reportar qualquer número." ], "a", "Diluir para a faixa calibrada e corrigir pelo fator de diluição é uma prática apropriada." ],
            [ "Qual trio relaciona corretamente técnica e propriedade medida?", [ "Cromatografia-separação; potenciometria-potencial; espectrofotometria-absorção de luz.", "Cromatografia-massa; potenciometria-cor; espectrofotometria-pressão.", "As três medem somente temperatura.", "As três dispensam calibração." ], "a", "Cada técnica explora uma propriedade diferente; controles e calibração continuam importantes." ]
          ])
      ]),
    track("Tecnologia Química", "tecnologia-quimica", "TQ", "#ead8bc",
      "Relacione reações, equipamentos e controle para compreender processos produtivos.",
      [
        module_data("Da matéria-prima ao produto", "Entenda fluxogramas, etapas de processo e transformação de matérias-primas.",
          "Tecnologia Química estuda como conhecimentos de química, física e engenharia são usados para produzir materiais em escala. Um processo pode incluir recebimento e preparo de matérias-primas, reação, separação, purificação, armazenamento e tratamento de correntes residuais. Nem toda etapa é uma reação: filtração e destilação são operações físicas, enquanto síntese e neutralização alteram a composição química.\n\nUm fluxograma representa etapas e correntes. Para interpretá-lo, acompanhe o sentido do fluxo, identifique entradas e saídas e pergunte qual função cada equipamento desempenha. Balanços de massa verificam a conservação; balanços de energia ajudam a estimar aquecimento e resfriamento. Conversão indica a fração de reagente consumida, seletividade compara a formação do produto desejado com produtos concorrentes e rendimento compara produção real com teórica.\n\nA escolha de condições industriais considera qualidade, produtividade, segurança, custo, consumo de energia e geração de resíduos. Um processo responsável procura prevenir perdas e emissões desde o projeto, em vez de depender apenas do tratamento no fim da linha.",
          "Na fabricação de um sal a partir de uma solução ácida e uma básica, a neutralização forma o produto dissolvido; evaporação ou cristalização pode recuperar o sólido. Um balanço inclui o que entra, o produto, a água removida e eventuais perdas.",
          "Em um fluxograma, uma etapa de filtração é usada principalmente para:", [ "Separar partículas sólidas de um fluido.", "Criar átomos de outro elemento.", "Medir pH sem instrumento.", "Aumentar a massa total." ], "a",
          "A filtração separa fisicamente sólidos suspensos de uma fase fluida.",
          [
            [ "Qual sequência é compatível com um processo químico de produção?", [ "Preparo, reação, separação e controle de qualidade.", "Somente rotulagem, sem verificar produto.", "Descartar matérias-primas antes de reagir.", "Medir temperatura sem fluxo de material." ], "a", "Um processo integra preparo, transformação, recuperação de produto e avaliação de qualidade." ],
            [ "Conversão de reagente mede:", [ "A fração do reagente alimentado que foi consumida.", "A cor do equipamento.", "O volume do tanque vazio.", "A concentração de água no ar." ], "a", "Conversão compara quantidade reagida com quantidade alimentada do reagente." ],
            [ "Se 100 kg entram e 95 kg são contabilizados nas saídas, sem reação ou acúmulo, a diferença sugere:", [ "Corrente não contabilizada, perda ou erro de medição.", "Criação de massa.", "Conversão exatamente 95%.", "Ausência de balanço." ], "a", "A diferença deve ser explicada por perdas, acúmulo ou medição incompleta." ],
            [ "Qual é um objetivo de controle de qualidade do produto?", [ "Verificar se características atendem à especificação definida.", "Aumentar o resíduo.", "Substituir segurança operacional.", "Evitar registrar os lotes." ], "a", "A especificação define critérios de aceitação de qualidade." ],
            [ "Seletividade de um processo relaciona:", [ "Formação do produto desejado frente a produtos concorrentes.", "Apenas pressão de entrada.", "Massa do recipiente.", "Número de operadores." ], "a", "Seletividade indica quanto da transformação favorece o produto alvo em relação aos demais produtos." ],
            [ "Por que se usa um fluxograma de processo?", [ "Para visualizar etapas e conexões entre correntes.", "Para substituir toda medição.", "Para indicar somente a cor do produto.", "Para eliminar balanços de massa." ], "a", "O fluxograma mostra equipamentos e correntes de material e energia." ],
            [ "Uma análise de risco de processo deve considerar:", [ "Perigos, condições operacionais e consequências de desvios.", "Somente preço do produto.", "Apenas nome da empresa.", "A cor dos tubos." ], "a", "Identificar perigos e cenários ajuda a prevenir acidentes e reduzir consequências." ],
            [ "Uma estratégia de produção mais limpa prioriza:", [ "Prevenir geração de resíduos e perdas na origem.", "Diluir todo resíduo e ignorar a origem.", "Aumentar consumo sem avaliar.", "Substituir controle por descarte." ], "a", "Prevenção reduz uso de recursos, poluição e custos ao longo do processo." ],
            [ "Qual indicador pode ajudar a comparar produção de um mesmo produto em períodos?", [ "Rendimento ou consumo específico de matéria-prima.", "Tamanho do logotipo.", "Cor do uniforme.", "Número de páginas do fluxograma." ], "a", "Indicadores de rendimento e consumo permitem acompanhar desempenho." ]
          ]),
        module_data("Balanços, rendimento e qualidade", "Aplique conservação de massa e indicadores para avaliar eficiência produtiva.",
          "O balanço de massa contabiliza as quantidades que entram, saem, são geradas, consumidas ou se acumulam em um sistema. Uma forma geral é entrada + geração − saída − consumo = acúmulo. Em processo contínuo estacionário, o acúmulo é zero. Em uma reação, espécies podem ser consumidas e formadas, mas a massa total continua conservada.\n\nO rendimento compara a quantidade real de produto com a quantidade teórica máxima calculada pela estequiometria. A conversão pergunta quanto de um reagente reagiu; seletividade pergunta quanto da reação favoreceu o produto desejado frente a reações secundárias. Esses indicadores não são sinônimos e ajudam a localizar problemas diferentes.\n\nA qualidade é definida por especificações mensuráveis, como composição, pureza, umidade ou faixa granulométrica. Amostragem e métodos de medição confiáveis são necessários para decidir se um lote atende à especificação. Quando os dados indicam desvio, investigue causas de processo antes de ajustar condições: mudanças não controladas podem aumentar risco ou piorar outras propriedades.",
          "Se o cálculo estequiométrico prevê 500 kg de produto e a planta obtém 425 kg, o rendimento é 425/500×100=85%. Esse resultado não informa sozinho se o reagente foi convertido completamente: parte pode ter reagido em rotas secundárias ou sido perdida na separação.",
          "Um processo produz 425 kg quando o máximo teórico é 500 kg. Qual é o rendimento?", [ "75%.", "80%.", "85%.", "118%." ], "c",
          "Rendimento=(425/500)×100=85%.",
          [
            [ "Em regime estacionário sem reação, a equação geral de balanço simplifica para:", [ "Entrada = saída.", "Entrada = acúmulo.", "Saída = geração.", "Massa total não se conserva." ], "a", "Sem reação e sem acúmulo, a entrada total deve igualar a saída." ],
            [ "A conversão de um reagente mede:", [ "Quanto dele reagiu em relação à quantidade alimentada.", "A pureza do solvente apenas.", "A seletividade do produto.", "A eficiência térmica do trocador." ], "a", "Conversão mede fração consumida do reagente." ],
            [ "Se um reagente alimentado é 100 mol e 80 mol reagem, a conversão é:", [ "20%.", "80%.", "100%.", "125%." ], "b", "Conversão=80/100×100=80%." ],
            [ "Um rendimento baixo pode resultar de:", [ "Reações secundárias, perdas de separação ou conversão incompleta.", "Conservação de massa.", "A presença de especificação.", "Uma balança calibrada." ], "a", "Várias etapas podem reduzir produto recuperado em relação ao máximo teórico." ],
            [ "Uma especificação de qualidade deve ser:", [ "Definida por critérios mensuráveis e relevantes ao uso.", "Alterada após cada lote sem registro.", "Somente verbal.", "Independente do produto." ], "a", "Critérios definidos permitem avaliar e comparar lotes." ],
            [ "Em um balanço com entrada 50 kg/h, saída 45 kg/h e sem reação, qual acúmulo ocorre?", [ "5 kg/h.", "45 kg/h.", "50 kg/h.", "95 kg/h." ], "a", "Entrada − saída=acúmulo=5 kg/h no sistema considerado." ],
            [ "Seletividade alta significa que:", [ "Uma proporção maior da transformação favorece o produto desejado.", "O processo não requer controle.", "Todo reagente permanece sem reagir.", "O rendimento deve ser zero." ], "a", "Seletividade compara produto alvo com produtos concorrentes." ],
            [ "Qual é a importância de amostragem representativa no controle de qualidade?", [ "A decisão deve refletir o lote, não uma porção enviesada.", "Evita qualquer calibração.", "Elimina todas as variações de processo.", "Garante rendimento de 100%." ], "a", "Uma amostra não representativa pode levar a uma conclusão errada sobre todo o lote." ],
            [ "Uma ação corretiva confiável deve se basear em:", [ "Investigação de causa e dados do processo.", "Ajuste aleatório de várias variáveis.", "Ocultação do resultado.", "Aumento de produção sem avaliar riscos." ], "a", "Identificar a causa evita correções que geram novos problemas." ]
          ])
      ]),
    track("Utilidades Industriais e Tratamento de Efluentes", "utilidades-efluentes", "UE", "#c9e2df",
      "Conheça vapor, água, ar comprimido e princípios de controle ambiental.",
      [
        module_data("Vapor, água e ar comprimido", "Entenda como utilidades fornecem energia e serviços a uma planta.",
          "Utilidades são sistemas de apoio que fornecem serviços para muitas áreas de uma instalação. Vapor pode transportar energia térmica; água pode servir a resfriamento, lavagem ou alimentação de processos, desde que sua qualidade seja adequada; ar comprimido pode acionar instrumentos e equipamentos. Cada aplicação exige especificações distintas: água de resfriamento não é automaticamente água potável ou água de processo.\n\nUma caldeira transfere calor para gerar vapor a partir de água. Tubulações, válvulas, purgadores e isolamento influenciam segurança e eficiência. Ar comprimido precisa ser tratado conforme a aplicação, removendo umidade ou partículas quando necessário. Sistemas utilitários requerem monitoramento de pressão, temperatura, vazão, qualidade e manutenção preventiva.\n\nVazamentos, isolamento inadequado e uso além do necessário desperdiçam energia e água. Uma visão de processo considera o consumo por setor, a possibilidade de reuso e os requisitos de segurança. Equipamentos pressurizados e vapor podem causar queimaduras e outros acidentes: sua operação requer treinamento, inspeção e procedimentos autorizados.",
          "Uma serpentina de vapor aquece um tanque enquanto a água condensada retorna ao sistema. Recuperar o condensado pode economizar água e energia, desde que sua qualidade e as condições do equipamento sejam verificadas.",
          "Qual utilidade é frequentemente usada para transportar calor a um equipamento de processo?", [ "Vapor.", "Areia.", "Resíduo sólido.", "Nitrogênio líquido sempre." ], "a",
          "Vapor pode fornecer energia térmica por condensação, sob controle e projeto apropriados.",
          [
            [ "Por que a qualidade da água deve ser definida conforme o uso?", [ "Porque água para resfriamento, processo e consumo têm requisitos diferentes.", "Porque toda água é quimicamente idêntica.", "Para evitar medir vazão.", "Porque água nunca causa incrustação." ], "a", "Aplicações diferentes têm exigências distintas de pureza e controle." ],
            [ "O condensado de vapor pode ser recuperado para:", [ "Economizar água e energia, após verificar sua adequação.", "Aumentar perdas térmicas.", "Substituir toda análise sem controle.", "Eliminar necessidade de manutenção." ], "a", "O retorno de condensado pode recuperar calor e água, com controles de qualidade." ],
            [ "Ar comprimido para instrumentação pode precisar de:", [ "Filtragem e remoção de umidade.", "Contaminação deliberada com óleo.", "Aquecimento até combustão.", "Mistura com efluente." ], "a", "Umidade ou partículas podem danificar instrumentos; o tratamento depende da especificação." ],
            [ "Qual prática ajuda a reduzir desperdício de utilidades?", [ "Detectar e reparar vazamentos.", "Manter válvulas abertas sem uso.", "Remover isolamento térmico.", "Aumentar pressão sem necessidade." ], "a", "Manutenção de vazamentos evita perdas de água, ar e energia." ],
            [ "O isolamento de uma linha de vapor serve para:", [ "Reduzir perdas de calor e risco de contato com superfícies quentes.", "Aumentar evaporação do ambiente.", "Alterar a fórmula da água.", "Substituir válvulas de segurança." ], "a", "Isolamento diminui troca térmica indesejada e pode reduzir risco de queimadura." ],
            [ "Qual variável é importante monitorar em um sistema pressurizado?", [ "Pressão.", "Cor do piso.", "Número de páginas do manual.", "Massa molar do ar." ], "a", "Pressão operacional deve permanecer dentro de condições seguras de projeto." ],
            [ "Um purgador de vapor tem como função típica:", [ "Remover condensado sem perder vapor vivo em condições adequadas.", "Adicionar sólidos à tubulação.", "Medir pH do vapor.", "Aumentar a corrosão." ], "a", "Purgadores removem condensado e ar do sistema de vapor com redução de perda de vapor." ],
            [ "Por que sistemas de vapor exigem inspeção e treinamento?", [ "Temperatura e pressão podem causar riscos graves.", "Vapor é sempre inofensivo.", "Inspeções alteram a composição da água.", "Treinamento reduz a vazão." ], "a", "Equipamentos pressurizados e quentes podem causar queimaduras e falhas perigosas." ],
            [ "Reuso de água industrial deve considerar:", [ "Qualidade exigida pelo próximo uso e riscos de contaminantes.", "Somente o volume disponível.", "A cor do reservatório.", "A eliminação de registros." ], "a", "A compatibilidade da qualidade da água com o processo receptor é essencial." ]
          ]),
        module_data("Efluentes e controle ambiental", "Conheça poluentes, tratamento e indicadores básicos de efluentes.",
          "Efluente é uma corrente líquida que deixa um processo ou atividade e pode conter sólidos, matéria orgânica, sais, nutrientes, metais ou outras substâncias. Antes de escolher um tratamento, é necessário conhecer origem, vazão, composição, variação ao longo do tempo e requisitos legais aplicáveis. Uma amostra deve representar a corrente e o plano de coleta precisa ser definido para a pergunta ambiental.\n\nO tratamento pode combinar etapas físicas, químicas e biológicas. Gradeamento e sedimentação retiram sólidos de determinados tamanhos; neutralização ajusta pH; coagulação e floculação ajudam a agregar partículas; processos biológicos degradam matéria orgânica biodegradável. Uma etapa isolada não remove necessariamente todos os contaminantes.\n\nIndicadores como pH, sólidos suspensos e demanda bioquímica ou química de oxigênio ajudam a caracterizar o efluente, mas não substituem a identificação de contaminantes específicos quando necessária. A hierarquia responsável começa pela prevenção e redução na origem, seguida de reúso e tratamento adequado. A descarga só deve ocorrer conforme autorizações, monitoramento e normas locais.",
          "Se uma corrente industrial ácida precisa de tratamento, a neutralização pode ajustar o pH, mas não elimina metais ou compostos orgânicos que também estejam presentes. A caracterização e as etapas adicionais precisam ser selecionadas para cada contaminante.",
          "Qual é a primeira etapa lógica antes de selecionar o tratamento de um efluente?", [ "Caracterizar origem, vazão e composição.", "Descartar sem análise.", "Adicionar qualquer reagente.", "Misturar com água potável até desaparecer a cor." ], "a",
          "A caracterização identifica contaminantes e condições necessárias para projetar o tratamento.",
          [
            [ "O pH de um efluente informa principalmente:", [ "Caráter ácido ou básico da solução.", "Massa total de sólidos.", "Vazão do rio.", "Demanda de oxigênio diretamente." ], "a", "pH indica a atividade de H₃O⁺ e o caráter ácido-básico em solução." ],
            [ "A sedimentação é útil principalmente para:", [ "Separar partículas que se depositam pela ação da gravidade.", "Destruir todos os sais dissolvidos.", "Medir temperatura.", "Remover qualquer gás dissolvido." ], "a", "Partículas suspensas suficientemente densas podem sedimentar." ],
            [ "A neutralização de um efluente ácido:", [ "Ajusta o pH, mas não garante remover todos os contaminantes.", "Remove necessariamente todos os metais.", "Esteriliza qualquer corrente.", "Substitui a caracterização." ], "a", "Neutralização altera acidez, mas contaminantes específicos podem exigir outros tratamentos." ],
            [ "A demanda bioquímica de oxigênio é relacionada a:", [ "Oxigênio consumido por atividade biológica ao degradar matéria orgânica biodegradável.", "Massa molar de metal.", "Cor do efluente apenas.", "Pressão de vapor." ], "a", "DBO estima consumo de oxigênio por degradação biológica sob condições de ensaio." ],
            [ "Por que reduzir a geração de efluente na origem é desejável?", [ "Evita poluição e pode reduzir consumo e custo de tratamento.", "Aumenta necessariamente a contaminação.", "Dispensa qualquer controle.", "Converte todos os resíduos em água." ], "a", "Prevenção diminui carga poluente e necessidade de tratamento." ],
            [ "O reúso de efluente tratado exige:", [ "Verificar se a qualidade é adequada ao uso pretendido.", "Usá-lo em qualquer finalidade sem avaliação.", "Remover todas as etiquetas.", "Misturar com reagentes desconhecidos." ], "a", "Requisitos variam com o uso e o risco de exposição ou contaminação." ],
            [ "Coagulação e floculação são usadas para:", [ "Facilitar agregação e remoção de partículas dispersas.", "Aumentar número atômico.", "Separar isótopos por massa.", "Medir somente pH." ], "a", "Agentes e mistura controlada podem formar flocos maiores que sedimentam ou filtram melhor." ],
            [ "Uma análise de efluente precisa de amostra representativa porque:", [ "A composição pode variar com o tempo e o fluxo.", "A água é sempre homogênea em qualquer escala.", "A amostra substitui a norma.", "A vazão não influencia cargas." ], "a", "Variações temporais e de vazão afetam a representatividade e a carga poluente." ],
            [ "Uma planta deve verificar padrões de descarte em:", [ "Normas e licenças aplicáveis à localidade e atividade.", "Somente livros antigos.", "Um valor universal sem contexto.", "Opinião informal." ], "a", "Limites e obrigações dependem da legislação e da licença aplicáveis." ]
          ])
      ]),
    track("Introdução aos Materiais e Corrosão", "materiais-corrosao", "MC", "#e7d2c9",
      "Compare materiais industriais e entenda como a corrosão pode ser prevenida.",
      [
        module_data("Materiais de engenharia e seleção", "Relacione propriedades de materiais com aplicações e condições de processo.",
          "Materiais industriais incluem metais, polímeros, cerâmicas e compósitos. Cada família combina propriedades diferentes. Metais costumam conduzir calor e eletricidade e podem deformar sem quebrar; cerâmicas tendem a ser duras e resistentes a altas temperaturas, mas podem ser frágeis; polímeros podem ser leves e resistentes a certos meios químicos, porém têm limites térmicos e mecânicos.\n\nA seleção depende das condições reais: temperatura, pressão, composição química, esforços, abrasão, limpeza, vida útil, custo e manutenção. Resistência mecânica, dureza, ductilidade, condutividade e resistência química descrevem aspectos distintos. Não existe material universalmente melhor; compatibilidade com o processo e segurança são essenciais.\n\nFichas técnicas e especificações devem ser consultadas antes da instalação. Um material adequado para água fria pode falhar em solvente, alta temperatura ou ambiente corrosivo. Inspeção e rastreabilidade ajudam a reconhecer desgaste e evitar falhas de equipamentos.",
          "Uma tubulação de água quente exige avaliação de temperatura, pressão, corrosividade da água e esforços. Escolher apenas pelo preço pode resultar em vazamento ou falha prematura; a especificação e a compatibilidade devem orientar a decisão.",
          "Qual conjunto de fatores é relevante na seleção de material para tubulação?", [ "Temperatura, pressão, fluido, esforço e manutenção.", "Somente a cor externa.", "Apenas a massa do operador.", "Somente o nome comercial." ], "a",
          "A seleção deve considerar condições de serviço, compatibilidade e requisitos de confiabilidade.",
          [
            [ "Ductilidade descreve a capacidade de um material de:", [ "Deformar plasticamente antes de fraturar.", "Conduzir apenas corrente alternada.", "Dissolver em água.", "Impedir qualquer transferência de calor." ], "a", "Ductilidade é a capacidade de deformação plástica, especialmente sob tração." ],
            [ "Qual família geralmente combina dureza elevada com fragilidade?", [ "Cerâmicas.", "Elastômeros.", "Gases nobres.", "Soluções aquosas." ], "a", "Muitas cerâmicas são duras e resistentes termicamente, mas pouco tolerantes a impacto." ],
            [ "Compatibilidade química de um material significa:", [ "Resistir ao meio de processo sem degradação inaceitável.", "Ter a mesma cor do fluido.", "Ser sempre metálico.", "Não exigir especificação." ], "a", "O material deve manter desempenho diante do fluido e das condições de serviço." ],
            [ "Por que a temperatura máxima de serviço importa para um polímero?", [ "Propriedades podem mudar ou o material pode degradar.", "A massa atômica se altera.", "O polímero vira metal.", "A corrosão desaparece." ], "a", "Temperatura pode amolecer, deformar ou degradar polímeros." ],
            [ "Um compósito é geralmente:", [ "Combinação de materiais para obter propriedades desejadas.", "Um elemento químico puro.", "Um líquido saturado.", "Uma solução sem soluto." ], "a", "Compósitos combinam fases ou materiais para melhorar propriedades específicas." ],
            [ "Qual propriedade mede resistência à deformação permanente por indentação?", [ "Dureza.", "Densidade.", "Solubilidade.", "pH." ], "a", "Dureza é associada à resistência à indentação ou risco, conforme o ensaio." ],
            [ "Uma especificação técnica de material deve incluir:", [ "Composição ou grau, dimensões, condições e requisitos aplicáveis.", "Apenas o fornecedor.", "Somente uma fotografia.", "Nenhuma condição de serviço." ], "a", "Especificações tornam verificáveis identidade, requisitos e uso pretendido." ],
            [ "Inspeções periódicas em equipamentos ajudam a:", [ "Detectar desgaste e defeitos antes de falhas graves.", "Alterar a composição do material.", "Dispensar projeto.", "Garantir ausência de todo risco." ], "a", "Inspeção apoia manutenção e identificação de degradação." ],
            [ "Ao comparar dois materiais, a decisão correta deve priorizar:", [ "Adequação ao serviço, segurança e custo do ciclo de vida.", "Apenas menor preço inicial.", "Apenas maior densidade.", "A escolha aleatória." ], "a", "Custo total inclui desempenho, manutenção e consequências de falha." ]
          ]),
        module_data("Corrosão e proteção", "Entenda a corrosão como processo de degradação e conheça estratégias de controle.",
          "Corrosão é a degradação de um material por interação com o ambiente. Em muitos metais, ocorre uma reação eletroquímica: em regiões anódicas, o metal se oxida e libera elétrons; em regiões catódicas, outra espécie consome esses elétrons. Água, oxigênio, sais, pH, temperatura e contato entre metais influenciam a velocidade.\n\nFerrugem é um conjunto de produtos de corrosão do ferro, não uma camada protetora uniforme. Em corrosão galvânica, dois metais diferentes em contato elétrico e um eletrólito podem formar uma célula; o metal menos nobre tende a corroer mais rapidamente. Frestas, depósitos e diferenças locais de aeração também podem criar corrosão localizada.\n\nA prevenção pode incluir seleção adequada de material, revestimentos, controle do meio, isolamento entre metais incompatíveis, proteção catódica e inibidores apropriados. A estratégia depende do mecanismo e da aplicação. Inspeção, limpeza e monitoramento são necessários para confirmar se a proteção continua funcionando.",
          "Conectar aço e cobre em presença de água salgada pode acelerar a corrosão do aço, dependendo das condições. Um projeto pode reduzir o risco isolando eletricamente os metais, usando materiais compatíveis e mantendo revestimentos íntegros.",
          "Na corrosão eletroquímica, na região anódica o metal geralmente:", [ "Oxida e libera elétrons.", "Reduz e consome elétrons.", "Não participa da reação.", "Vira nêutron." ], "a",
          "Oxidação é perda de elétrons; o metal anódico tende a passar para íons.",
          [
            [ "Qual conjunto pode acelerar corrosão de aço?", [ "Umidade, oxigênio e sais.", "Somente luz visível.", "Vácuo perfeito.", "Ausência de eletrólito." ], "a", "Água e eletrólitos facilitam processos eletroquímicos; oxigênio participa de reações catódicas comuns." ],
            [ "Corrosão galvânica requer tipicamente:", [ "Metais diferentes em contato elétrico e um eletrólito.", "Dois polímeros isolados.", "Somente ar seco.", "Uma balança calibrada." ], "a", "A célula galvânica necessita de caminho eletrônico e iônico." ],
            [ "Um revestimento protege o metal quando:", [ "Atua como barreira e permanece íntegro.", "Aumenta contato com eletrólito.", "Tem fissuras profundas.", "Substitui inspeção em qualquer caso." ], "a", "Revestimentos isolam o substrato do ambiente enquanto não há falhas relevantes." ],
            [ "Proteção catódica busca:", [ "Fazer a estrutura protegida atuar como cátodo.", "Aumentar a oxidação do metal protegido.", "Remover todo o metal.", "Elevar pH obrigatoriamente a 14." ], "a", "A proteção catódica reduz a dissolução anódica da estrutura." ],
            [ "A ferrugem do ferro é:", [ "Produto de corrosão que pode conter óxidos e hidróxidos hidratados.", "Ferro puro polido.", "Uma liga de cobre.", "Uma camada sempre impermeável." ], "a", "Ferrugem é uma mistura de produtos de corrosão, frequentemente porosa e pouco protetora." ],
            [ "Um defeito no revestimento de uma tubulação:", [ "Pode expor o metal e criar ponto local de corrosão.", "Garante proteção melhor.", "Elimina o eletrólito.", "Transforma o material em cerâmica." ], "a", "Descontinuidades podem concentrar ataque no substrato exposto." ],
            [ "Um inibidor de corrosão é usado para:", [ "Reduzir a velocidade de corrosão em condições apropriadas.", "Aumentar sempre a temperatura.", "Remover toda necessidade de monitoramento.", "Criar uma nova liga automaticamente." ], "a", "Inibidores interferem em etapas do processo corrosivo, quando compatíveis e controlados." ],
            [ "Por que isolar metais diferentes em contato?", [ "Para interromper o caminho elétrico da célula galvânica.", "Para aumentar a diferença de potencial.", "Para dissolver o eletrólito.", "Para eliminar o peso." ], "a", "Isolamento elétrico pode interromper a corrente galvânica entre metais." ],
            [ "A escolha de uma proteção anticorrosiva deve considerar:", [ "Mecanismo, ambiente, material, manutenção e custo.", "Apenas a aparência.", "Somente a espessura do tanque.", "A cor do uniforme." ], "a", "A proteção é específica para material, ambiente e condições de exposição." ]
          ])
      ]),
    track("Equipamentos Industriais, Automação e Controle de Processos", "equipamentos-controle-processos", "EC", "#ded8ee",
      "Conheça equipamentos de processo, instrumentação, automação e controle.",
      [
        module_data("Equipamentos industriais e instrumentos", "Identifique a função de bombas, válvulas, tanques e instrumentos de medição.",
          "Uma planta química usa equipamentos para armazenar, transportar, aquecer, resfriar e separar materiais. Tanques mantêm inventário; bombas deslocam líquidos; compressores elevam pressão de gases; trocadores transferem calor; reatores promovem transformações; válvulas regulam ou interrompem vazões. Cada equipamento precisa ser escolhido para a faixa de operação, fluido, pressão, temperatura e risco.\n\nInstrumentos medem variáveis como temperatura, pressão, nível e vazão. Um transmissor converte a medição em sinal que pode ser enviado a um controlador ou sistema de supervisão. Medição adequada exige faixa, resolução, instalação e calibração compatíveis. Uma leitura incorreta pode conduzir a decisões erradas mesmo que o controlador funcione como projetado.\n\nDiagramas de processo e instrumentação identificam equipamentos, linhas, válvulas e instrumentos com símbolos e códigos padronizados. Saber seguir uma linha e reconhecer os elementos ajuda a entender operação e manutenção. Equipamentos sob pressão, partes móveis e fluidos perigosos requerem proteções, inspeção e procedimentos específicos.",
          "Em um tanque, um sensor mede nível; seu transmissor envia o valor ao controlador, que pode ajustar a abertura de uma válvula de saída. A válvula não mede o nível: ela é o elemento final que altera o processo.",
          "Qual é a função típica de uma bomba centrífuga em uma planta?", [ "Transferir energia ao líquido para promover escoamento.", "Medir pH.", "Separar moléculas por absorção de luz.", "Controlar diretamente a composição sem instrumento." ], "a",
          "A bomba fornece energia hidráulica para movimentar líquido no sistema.",
          [
            [ "Qual instrumento mede a pressão de uma linha?", [ "Manômetro ou transmissor de pressão.", "Termopar.", "Balança analítica.", "Condensador." ], "a", "Manômetros e transmissores apropriados medem pressão." ],
            [ "Um trocador de calor serve principalmente para:", [ "Transferir energia térmica entre correntes.", "Medir massa.", "Armazenar dados de laboratório.", "Filtrar moléculas por tamanho." ], "a", "O equipamento promove troca de calor, geralmente sem mistura das correntes." ],
            [ "Uma válvula de controle é normalmente:", [ "Elemento final que altera vazão ou outra variável manipulada.", "Sensor que mede diretamente todas as variáveis.", "Padrão de calibração.", "Reator químico." ], "a", "A válvula recebe ação de controle e modifica a condição do processo." ],
            [ "Por que calibração de instrumento é importante?", [ "Relacionar a indicação a valores de referência e detectar desvios.", "Aumentar pressão de processo.", "Eliminar toda necessidade de manutenção.", "Alterar a composição do fluido." ], "a", "A calibração verifica e estabelece relação entre indicação e referência." ],
            [ "Um transmissor de temperatura converte:", [ "Medição em sinal para monitoramento ou controle.", "Massa em produto químico.", "Vapor em água sem condensador.", "Pressão em número atômico." ], "a", "Transmissores enviam sinais relacionados à variável medida." ],
            [ "O nível em um tanque é uma medida de:", [ "Altura ou quantidade de material armazenado.", "Concentração molar necessariamente.", "Temperatura ambiente.", "Corrente elétrica do motor somente." ], "a", "Instrumentos de nível acompanham altura ou inventário de conteúdo." ],
            [ "Um compressor é usado principalmente para:", [ "Elevar a pressão de gases.", "Bombear sólidos em filtro.", "Medir massa.", "Neutralizar efluentes." ], "a", "Compressores aumentam pressão de correntes gasosas." ],
            [ "Um equipamento projetado para uma pressão menor que a operação planejada representa:", [ "Risco de falha e condição insegura.", "Melhoria de eficiência garantida.", "Apenas questão estética.", "Uma calibração válida." ], "a", "Pressão deve respeitar os limites de projeto e dispositivos de segurança." ],
            [ "Diagramas de processo e instrumentação ajudam a:", [ "Visualizar conexões, equipamentos e instrumentos.", "Substituir treinamento.", "Definir fórmulas moleculares.", "Eliminar qualquer inspeção." ], "a", "Diagramas documentam a arquitetura e as relações de processo." ]
          ]),
        module_data("Automação e controle de processos", "Entenda sensores, controladores, realimentação e resposta a desvios.",
          "Controle de processos mantém uma variável próxima de um valor desejado, chamado setpoint. Um sensor mede a variável controlada; um controlador compara a medição com o setpoint e calcula uma ação; um elemento final, como uma válvula, altera o processo. A diferença entre o valor desejado e o medido é o erro.\n\nEm controle por realimentação, a medição é usada continuamente para corrigir desvios. Um exemplo é controlar temperatura de tanque ajustando a vazão de vapor. Perturbações, como mudança na alimentação ou na temperatura ambiente, podem afastar a variável do objetivo; o controlador responde de acordo com seu ajuste.\n\nUm controle mal ajustado pode oscilar, responder lentamente ou ultrapassar limites. Alarmes informam condições que exigem atenção; intertravamentos podem levar o equipamento a um estado seguro quando condições perigosas são detectadas. Automação não substitui projeto seguro, manutenção, treinamento nem resposta humana a anomalias.",
          "Se o setpoint de temperatura é 60 °C e o sensor indica 55 °C, o erro é +5 °C (setpoint menos medição). Um controlador pode abrir a válvula de vapor para fornecer mais calor, respeitando limites e proteções do sistema.",
          "Em uma malha de controle, quem mede a variável do processo?", [ "Sensor.", "Válvula de controle.", "Tanque de armazenamento.", "Produto acabado." ], "a",
          "O sensor mede a variável e envia a informação para o controlador.",
          [
            [ "O setpoint é:", [ "O valor desejado para a variável controlada.", "O valor máximo do estoque.", "O nome do sensor.", "A massa do produto." ], "a", "Setpoint é o alvo definido para uma malha de controle." ],
            [ "O erro de controle costuma ser calculado como:", [ "Setpoint menos medição.", "Medição mais massa molar.", "Pressão vezes volume.", "Temperatura menos vazão sempre." ], "a", "O erro é a diferença entre o valor desejado e o medido, segundo a convenção do controlador." ],
            [ "O que é uma perturbação em um processo?", [ "Mudança externa que afeta a variável controlada.", "O setpoint.", "A calibração do sensor.", "O nome da válvula." ], "a", "Perturbação altera o processo sem ser a ação de controle desejada." ],
            [ "Controle por realimentação usa:", [ "A medição da saída para ajustar a ação.", "Apenas um plano sem medir.", "Somente a temperatura ambiente.", "Um alarme sem sensor." ], "a", "A saída medida é comparada com o objetivo para corrigir desvios." ],
            [ "Qual exemplo é um elemento final de controle?", [ "Válvula que regula vazão.", "Sensor de temperatura.", "Tela de supervisório.", "Padrão certificado." ], "a", "A válvula modifica fisicamente a condição manipulada do processo." ],
            [ "Um alarme de alta pressão indica:", [ "Uma condição que requer avaliação conforme procedimento.", "Que o transmissor é dispensável.", "Que a pressão deve ser ignorada.", "Uma medição de concentração." ], "a", "Alarmes chamam atenção a desvios; a resposta depende do plano operacional." ],
            [ "Intertravamentos de segurança têm como objetivo:", [ "Levar o processo a condição segura diante de cenários definidos.", "Aumentar a produção em qualquer situação.", "Substituir todas as válvulas.", "Ignorar sensores." ], "a", "Intertravamentos executam ações protetivas quando condições predeterminadas ocorrem." ],
            [ "Se a medição oscila continuamente ao redor do setpoint, uma possibilidade é:", [ "Ajuste inadequado do controlador ou dinâmica do processo.", "Massa não conservada.", "Ausência de variável medida.", "Conversão do fluido em sólido." ], "a", "Oscilações podem indicar sintonia inadequada, atraso ou interação do processo." ],
            [ "Automação industrial deve ser acompanhada por:", [ "Análise de risco, manutenção e procedimentos operacionais.", "Ausência de treinamento.", "Desativação de alarmes.", "Operação além do limite de projeto." ], "a", "Automação complementa, mas não substitui, práticas de segurança e manutenção." ]
          ])
      ]),
    track("Gestão de Processos Industriais e Empreendedorismo", "gestao-processos-empreendedorismo", "GP", "#ead0bd",
      "Aprenda a mapear processos, acompanhar indicadores e avaliar ideias de negócio.",
      [
        module_data("Gestão da produção e melhoria contínua", "Organize processos com foco em qualidade, eficiência e segurança.",
          "Gerir um processo é definir como pessoas, materiais, equipamentos e informações se organizam para entregar um resultado. Mapear o processo ajuda a reconhecer etapas, entradas, saídas, responsáveis e pontos de decisão. Indicadores devem responder a uma pergunta prática, como rendimento, consumo de água por lote, tempo de ciclo ou taxa de retrabalho.\n\nUm indicador precisa de definição, unidade, fonte de dados, frequência e responsável. Comparar dados ao longo do tempo permite identificar tendências, mas uma mudança observada não prova sozinha a causa. Investigue condições operacionais, matéria-prima, equipamento, medição e treinamento antes de propor uma ação corretiva.\n\nMelhoria contínua pode seguir ciclos de planejar, executar em escala controlada, verificar resultados e agir com base nas evidências. Segurança, qualidade e meio ambiente não são metas concorrentes que podem ser ignoradas para aumentar volume; devem ser requisitos do processo. Mudanças precisam ser avaliadas, documentadas e comunicadas.",
          "Se o consumo de água aumenta de 2,0 para 3,1 m³ por tonelada produzida, o indicador aponta um desvio a investigar. Verifique vazamentos, limpeza, qualidade do produto e medições antes de alterar o processo.",
          "Qual é uma utilidade de um indicador de processo bem definido?", [ "Acompanhar desempenho com unidade, método e frequência conhecidos.", "Substituir todas as inspeções.", "Garantir causa sem investigação.", "Evitar registro de produção." ], "a",
          "Indicadores consistentes permitem acompanhar tendências e orientar investigação.",
          [
            [ "Um fluxograma de processo pode mostrar:", [ "Etapas, entradas, saídas e decisões.", "Somente nomes de funcionários.", "Apenas despesas pessoais.", "Resultados sem unidades." ], "a", "O mapeamento representa o fluxo e os pontos relevantes do processo." ],
            [ "Uma ação corretiva deve ser tomada após:", [ "Investigar a causa do desvio e avaliar riscos da mudança.", "Alterar várias variáveis aleatoriamente.", "Esconder dados.", "Aumentar produção sem controle." ], "a", "A investigação evita ações que tratam sintomas ou criam outros riscos." ],
            [ "Qual característica torna um indicador útil?", [ "Definição clara, unidade, fonte e frequência.", "Nome vago sem dados.", "Mudança de cálculo a cada lote.", "Ausência de responsável." ], "a", "Consistência torna os valores comparáveis e rastreáveis." ],
            [ "O ciclo de melhoria contínua envolve:", [ "Planejar, executar, verificar e agir.", "Produzir, ignorar, descartar e ocultar.", "Medir uma vez e concluir.", "Comprar equipamento sem avaliar." ], "a", "O ciclo testa mudanças, verifica efeitos e padroniza ou corrige conforme dados." ],
            [ "Se a taxa de retrabalho aumenta, a melhor resposta inicial é:", [ "Analisar dados e causas potenciais.", "Ignorar porque há produção.", "Reduzir o controle de qualidade.", "Mudar a especificação sem registro." ], "a", "A investigação identifica onde e por que surgem falhas." ],
            [ "Por que uma mudança de processo precisa ser documentada?", [ "Para manter rastreabilidade, comunicar equipes e avaliar consequências.", "Para aumentar burocracia sem objetivo.", "Para dispensar treinamento.", "Para apagar o histórico." ], "a", "Documentação sustenta segurança, repetibilidade e aprendizado." ],
            [ "Qual indicador pode avaliar produtividade?", [ "Quantidade produzida por período, considerando a especificação.", "Cor da parede.", "Número de crachás.", "Massa molar da água." ], "a", "Produção por tempo é um indicador possível, desde que qualidade e contexto sejam considerados." ],
            [ "A gestão responsável de um processo deve equilibrar:", [ "Qualidade, produtividade, segurança e impactos ambientais.", "Somente volume produzido.", "Apenas custo imediato.", "Marketing e cor do uniforme." ], "a", "Metas de desempenho devem ser integradas a segurança e meio ambiente." ],
            [ "Uma tendência de aumento de consumo específico pode indicar:", [ "Mudança de eficiência ou desvio que merece investigação.", "Que o indicador perdeu toda utilidade.", "Que a produção sempre melhorou.", "Que a unidade está errada necessariamente." ], "a", "Tendências são sinais para análise de causas e confirmação dos dados." ]
          ]),
        module_data("Empreendedorismo e viabilidade", "Transforme uma necessidade em proposta testável e avalie recursos e riscos.",
          "Empreendedorismo começa com a identificação de uma necessidade e a construção de uma proposta de valor: quem será atendido, qual problema existe e como a solução ajuda. Uma ideia não é um negócio viável apenas por ser interessante; é preciso conversar com usuários, observar alternativas existentes e testar hipóteses com baixo custo.\n\nUm modelo de negócio descreve clientes, proposta de valor, canais, recursos, atividades, parceiros, custos e fontes de receita. Uma estimativa simples de viabilidade compara custos fixos e variáveis com o preço e o volume de vendas esperados. As estimativas têm incerteza e devem ser explicitadas; cenários ajudam a perceber como mudanças de preço, demanda ou insumos afetam o resultado.\n\nEm produtos químicos, também devem ser avaliados segurança, conformidade regulatória, rotulagem, transporte, descarte, qualidade e responsabilidade ambiental. A comunicação de riscos e o atendimento às normas são parte do produto e da operação, não detalhes posteriores.",
          "Uma equipe pensa em produzir detergente biodegradável para pequenos comércios. Antes de comprar equipamentos, pode entrevistar possíveis clientes, testar uma formulação segura em escala apropriada, calcular custo por unidade e verificar requisitos legais e de rotulagem.",
          "Qual é uma boa primeira etapa para testar uma ideia de negócio?", [ "Validar a necessidade e as hipóteses com potenciais usuários.", "Comprar imediatamente uma planta industrial.", "Ignorar custos e normas.", "Definir receita garantida sem dados." ], "a",
          "Conversar com usuários e testar hipóteses reduz incerteza antes de comprometer recursos.",
          [
            [ "Proposta de valor descreve:", [ "Benefício e problema atendido para um público.", "Somente o nome da empresa.", "O balanço de massa de todo o mercado.", "Uma garantia de lucro." ], "a", "A proposta explica por que um cliente escolheria a solução." ],
            [ "Custos variáveis tendem a:", [ "Mudar com o volume produzido.", "Permanecer iguais em qualquer volume.", "Não existir em produção química.", "Ser iguais à receita." ], "a", "Matérias-primas e embalagens costumam variar com o volume produzido." ],
            [ "Por que estimar cenários de demanda?", [ "Para avaliar como incertezas afetam custos e viabilidade.", "Para eliminar qualquer risco.", "Para garantir venda.", "Para substituir pesquisa com clientes." ], "a", "Cenários mostram sensibilidade do resultado a premissas diferentes." ],
            [ "Um protótipo ou teste inicial serve para:", [ "Obter evidências sobre hipóteses antes de escalar.", "Substituir a avaliação de segurança.", "Garantir aprovação regulatória.", "Eliminar necessidade de qualidade." ], "a", "Testes pequenos e controlados ajudam a aprender antes de investimentos maiores." ],
            [ "Em um produto químico, rotulagem e segurança devem ser consideradas:", [ "Desde o projeto e antes da comercialização.", "Somente depois de um acidente.", "Apenas se o produto for colorido.", "Nunca para pequenos lotes." ], "a", "Requisitos de segurança e conformidade fazem parte do desenvolvimento responsável." ],
            [ "Ponto de equilíbrio financeiro é relacionado a:", [ "Nível em que receitas cobrem custos totais.", "Temperatura de ebulição.", "pH neutro.", "Massa molar do produto." ], "a", "No ponto de equilíbrio, resultado operacional é nulo sob as premissas usadas." ],
            [ "Qual hipótese deve ser validada com clientes?", [ "Se o problema é importante e a solução é desejada.", "Se a gravidade existe.", "Se a massa se conserva.", "Se o rótulo cabe em qualquer frasco." ], "a", "Validação de mercado testa necessidades, uso e disposição para adotar." ],
            [ "Uma decisão de investimento responsável considera:", [ "Demanda, custos, riscos, requisitos e recursos.", "Somente entusiasmo.", "Apenas o preço de venda.", "Promessa sem evidências." ], "a", "Viabilidade integra fatores de mercado, operação, segurança e finanças." ],
            [ "Uma fonte de receita representa:", [ "Como a organização recebe valor econômico pela oferta.", "O resíduo gerado.", "O custo fixo.", "A concentração do ingrediente." ], "a", "Receita é a entrada financeira associada à venda ou ao serviço." ]
          ])
      ]),
    track("Segurança do Trabalho e Meio Ambiente", "seguranca-trabalho-meio-ambiente", "SM", "#d8e6d9",
      "Integre prevenção de riscos ocupacionais, práticas seguras e responsabilidade ambiental.",
      [
        module_data("Perigos, riscos e prevenção", "Aprenda a reconhecer perigos e selecionar medidas de controle.",
          "Perigo é uma fonte ou situação com potencial de causar dano; risco combina a probabilidade de ocorrência com a gravidade possível. Um produto corrosivo, uma parte móvel e uma superfície quente são perigos distintos e pedem controles diferentes. A avaliação começa identificando tarefas, agentes, pessoas expostas e cenários de falha.\n\nA hierarquia de controles prioriza eliminar o perigo, substituir por alternativa menos perigosa, aplicar controles de engenharia, organizar procedimentos e, por fim, usar equipamentos de proteção individual. EPI é importante, mas depende de seleção, ajuste, uso e manutenção; não corrige um processo mal projetado. Sinalização e treinamento complementam controles físicos.\n\nPlanos de emergência definem comunicação, rotas de fuga, alarmes, equipamentos e responsabilidades. Todo incidente e quase acidente deve ser comunicado para aprender e prevenir repetição. Regras específicas variam por legislação e local de trabalho; siga as normas vigentes e orientações de profissionais responsáveis.",
          "Para reduzir exposição a vapor de solvente, a prioridade é avaliar se o solvente pode ser substituído e usar sistema fechado ou exaustão local. Luvas e proteção respiratória só devem ser selecionadas conforme avaliação e procedimento aplicável.",
          "Na hierarquia de controles, qual medida tem prioridade sobre o uso isolado de EPI?", [ "Eliminar ou substituir o perigo, quando possível.", "Ignorar o perigo.", "Aumentar o tempo de exposição.", "Retirar a sinalização." ], "a",
          "Eliminar ou substituir o perigo reduz o risco na origem e tem prioridade na hierarquia.",
          [
            [ "Perigo é:", [ "Fonte com potencial de causar dano.", "Probabilidade multiplicada por gravidade apenas.", "Um equipamento de proteção.", "Um resultado de análise." ], "a", "Perigo descreve a fonte ou condição capaz de causar dano." ],
            [ "Risco considera principalmente:", [ "Probabilidade e consequência do dano.", "Somente cor e odor.", "Número de operadores.", "Massa molar." ], "a", "A avaliação de risco combina chance de ocorrência e severidade." ],
            [ "Qual exemplo é controle de engenharia?", [ "Exaustão local para capturar vapores.", "Cartaz sem mudança física.", "EPI sem avaliar compatibilidade.", "Ignorar vazamento." ], "a", "Ventilação local controla exposição na fonte por meio de engenharia." ],
            [ "EPI deve ser escolhido:", [ "Conforme o perigo, compatibilidade e avaliação da tarefa.", "Pela aparência.", "Sem verificar a ficha de segurança.", "Sempre igual para qualquer produto." ], "a", "O equipamento precisa proteger contra o risco específico e ser utilizado corretamente." ],
            [ "Um quase acidente deve ser comunicado porque:", [ "Pode revelar falha de controle antes de uma lesão.", "Não tem valor preventivo.", "Substitui treinamento.", "Serve apenas para punir." ], "a", "Analisar quase acidentes oferece oportunidade de prevenção." ],
            [ "Em uma emergência, a primeira resposta deve seguir:", [ "Plano local e instruções de pessoas responsáveis.", "Improviso individual.", "Mistura de produtos desconhecidos.", "Continuidade do experimento." ], "a", "Planos definem ações seguras, comunicação e evacuação conforme o cenário." ],
            [ "Substituição na hierarquia de controle significa:", [ "Trocar agente ou processo por alternativa de menor perigo.", "Trocar um EPI por outro sem avaliar.", "Alterar o rótulo.", "Aumentar a concentração." ], "a", "Substituir reduz o perigo na origem quando existe alternativa segura." ],
            [ "Uma análise de tarefa segura deve ser realizada:", [ "Antes da atividade e quando condições mudam.", "Somente após acidente grave.", "Apenas uma vez na vida.", "Depois de descartar os resíduos." ], "a", "Mudanças de tarefa, equipamento ou material podem criar novos riscos." ],
            [ "Treinamento de segurança deve incluir:", [ "Perigos, controles e resposta a emergências relevantes.", "Somente nomes dos produtos.", "Promessas de risco zero.", "Apenas assinatura de presença." ], "a", "Treinamento efetivo prepara para prevenção e ação correta." ]
          ]),
        module_data("Resíduos, meio ambiente e conformidade", "Relacione prevenção, segregação e acompanhamento de impactos ambientais.",
          "Impactos ambientais podem ocorrer no uso de água e energia, na geração de resíduos, nas emissões para o ar e nos efluentes líquidos. A avaliação considera aspecto (atividade ou elemento que interage com o ambiente) e impacto (mudança resultante), além de escala, frequência, duração e exigências aplicáveis.\n\nA hierarquia de gestão de resíduos prioriza evitar a geração, reduzir, reutilizar e reciclar quando seguros e permitidos; tratamento e disposição são opções posteriores. Resíduos químicos devem ser segregados por compatibilidade, identificados e armazenados em recipientes adequados. Misturar resíduos desconhecidos pode gerar calor, gases ou reações perigosas.\n\nMonitoramento e registros ajudam a demonstrar conformidade e identificar desvios, mas limites e procedimentos dependem da legislação, licença e atividade. Reutilizar água ou subprodutos exige verificar qualidade e riscos no novo uso. Em todos os casos, consulte responsáveis ambientais e normas locais; uma prática responsável evita prometer que um processo ou produto é «sem impacto».",
          "Um laboratório pode reduzir o impacto ao planejar ensaios em microescala, evitar excesso de reagentes, segregar corretamente os resíduos e registrar sua destinação. Reutilizar um solvente exige avaliar pureza, segurança e adequação ao procedimento seguinte.",
          "Qual ação está no topo da hierarquia de gestão de resíduos?", [ "Prevenir a geração.", "Descartar em aterro.", "Diluir e lançar na pia.", "Misturar resíduos para reduzir rótulos." ], "a",
          "A prevenção evita consumo de recursos e geração de resíduo antes que o tratamento seja necessário.",
          [
            [ "Por que segregar resíduos químicos?", [ "Para evitar incompatibilidades e permitir destinação correta.", "Para misturar tudo em um recipiente.", "Para eliminar identificação.", "Para aumentar o volume total." ], "a", "Segregação reduz riscos de reação e ajuda na gestão e destinação apropriadas." ],
            [ "Reutilizar uma corrente exige:", [ "Confirmar qualidade e compatibilidade com o novo uso.", "Usar sem analisar.", "Misturar com resíduo desconhecido.", "Ignorar exposição ocupacional." ], "a", "O novo uso precisa atender a requisitos de qualidade e segurança." ],
            [ "Aspecto ambiental é:", [ "Elemento da atividade que pode interagir com o ambiente.", "O efeito ambiental em si.", "Um equipamento de laboratório.", "A concentração de um padrão." ], "a", "Aspecto é a fonte de interação; impacto é a alteração ambiental associada." ],
            [ "O registro de destinação de resíduo ajuda a:", [ "Manter rastreabilidade e demonstrar gestão adequada.", "Substituir rótulos.", "Eliminar necessidade de segregação.", "Alterar propriedades químicas." ], "a", "Rastreabilidade registra o caminho do resíduo e seu destino." ],
            [ "Qual medida reduz consumo de água sem comprometer segurança?", [ "Corrigir vazamentos e otimizar etapas de lavagem.", "Deixar torneiras abertas.", "Usar água potável para qualquer finalidade.", "Desativar monitoramento." ], "a", "Manutenção e otimização diminuem consumo sem abandonar critérios de qualidade." ],
            [ "Uma licença ambiental pode definir:", [ "Condições, limites e obrigações de monitoramento.", "Somente a cor dos tanques.", "A fórmula do produto.", "O número de operadores sem relação com risco." ], "a", "Licenças estabelecem condicionantes de operação e controle ambiental." ],
            [ "Por que não se deve descartar solvente no ralo sem autorização?", [ "Pode causar risco, poluição e violar requisitos aplicáveis.", "Porque todo solvente é água.", "Porque o ralo neutraliza qualquer substância.", "Porque evapora sem impacto." ], "a", "Solventes podem ser perigosos e sua destinação deve seguir procedimento e legislação." ],
            [ "Qual ação representa prevenção na origem?", [ "Reduzir excesso de reagente já na etapa de planejamento.", "Tratar todo resíduo somente ao final.", "Aumentar descarte.", "Misturar substâncias incompatíveis." ], "a", "Planejamento adequado evita geração desnecessária de resíduo." ],
            [ "Uma avaliação de impacto deve considerar:", [ "Magnitude, duração, frequência e requisitos aplicáveis.", "Apenas o nome do setor.", "Somente a cor do efluente.", "Nenhum dado quantitativo." ], "a", "Caracterizar o impacto exige avaliar sua escala e contexto." ]
          ])
      ]),
    track("Estágio Curricular e TCC", "estagio-curricular-tcc", "ET", "#d7dce9",
      "Prepare-se para aprender no ambiente profissional e comunicar um trabalho técnico.",
      [
        module_data("Estágio: aprendizagem e responsabilidade", "Entenda objetivos, registros e conduta durante a experiência profissional.",
          "O estágio aproxima o estudante das atividades profissionais e ajuda a relacionar teoria, prática, segurança e organização do trabalho. Antes de iniciar, compreenda objetivos de aprendizagem, atividades permitidas, supervisão, horários, confidencialidade e procedimentos da instituição. Não execute tarefa para a qual não recebeu autorização e treinamento.\n\nUm diário ou registro de atividades deve descrever o que foi feito, em que contexto, quais procedimentos foram seguidos e o que foi aprendido, respeitando informações confidenciais. Quando houver dúvida, peça orientação ao supervisor. Incidentes, desvios e riscos devem ser comunicados pelos canais apropriados; improvisar pode comprometer pessoas, equipamentos e resultados.\n\nA avaliação do estágio considera aprendizagem e responsabilidade, não apenas horas cumpridas. Use feedback para identificar competências a desenvolver, como leitura de procedimentos, registro de dados, comunicação, organização e trabalho em equipe. Regras formais de estágio variam conforme instituição e legislação; confirme requisitos vigentes com a coordenação.",
          "Ao acompanhar preparo de solução, registre o objetivo, os instrumentos observados, as etapas autorizadas e os controles de segurança, sem copiar dados restritos. Se a atividade divergir do procedimento, interrompa e pergunte ao supervisor antes de prosseguir.",
          "Qual é a conduta adequada diante de uma tarefa de laboratório para a qual o estudante não foi treinado?", [ "Executá-la sozinho para aprender.", "Pedir orientação e autorização ao supervisor antes de agir.", "Ignorar o procedimento.", "Delegar a outro estudante sem supervisão." ], "b",
          "Atividades precisam de autorização e treinamento; dúvidas devem ser encaminhadas ao supervisor.",
          [
            [ "Um registro de estágio útil deve:", [ "Descrever atividades e aprendizados com data e contexto.", "Conter apenas opiniões sem fatos.", "Omitir qualquer procedimento.", "Incluir dados confidenciais sem autorização." ], "a", "Registros organizados ajudam a refletir sobre a experiência e comprovar atividades." ],
            [ "Por que preservar confidencialidade no estágio?", [ "Para proteger dados e informações da organização.", "Para impedir todo aprendizado.", "Para evitar segurança.", "Para esconder incidentes." ], "a", "Informações técnicas e dados podem estar sujeitos a regras de confidencialidade." ],
            [ "Em caso de incidente, o estudante deve:", [ "Comunicar rapidamente conforme o procedimento do local.", "Ocultar para não interromper produção.", "Apagar registros.", "Tentar resolver sozinho qualquer situação." ], "a", "Comunicação imediata permite resposta segura e investigação." ],
            [ "O feedback do supervisor serve para:", [ "Orientar desenvolvimento de competências.", "Substituir todos os objetivos.", "Punir automaticamente.", "Dispensar reflexão." ], "a", "Feedback ajuda a reconhecer pontos fortes e necessidades de aprendizagem." ],
            [ "Uma competência profissional inclui:", [ "Seguir procedimentos e comunicar desvios.", "Improvisar diante de risco.", "Evitar registrar dados.", "Ignorar limites de autorização." ], "a", "Responsabilidade inclui execução conforme procedimentos e comunicação." ],
            [ "O relatório de estágio deve respeitar:", [ "Orientações da instituição e confidencialidade.", "Apenas preferência visual.", "Dados sem fonte.", "Informações inventadas." ], "a", "Formato e conteúdo devem cumprir os requisitos acadêmicos e proteger dados." ],
            [ "A carga horária do estágio:", [ "Precisa ser verificada conforme regras institucionais e legais.", "É igual em todas as instituições.", "Pode ser inventada.", "Substitui todos os objetivos de aprendizagem." ], "a", "Requisitos formais variam e devem ser confirmados com a instituição." ],
            [ "Se um procedimento não está claro, a melhor ação é:", [ "Perguntar ao supervisor antes de executá-lo.", "Adivinhar e continuar.", "Pular etapas sem comunicar.", "Alterar reagentes." ], "a", "Esclarecer instruções reduz riscos e erros." ],
            [ "A reflexão sobre uma atividade profissional ajuda a:", [ "Relacionar prática, teoria e próximos objetivos de aprendizagem.", "Esconder dificuldades.", "Eliminar necessidade de supervisão.", "Aumentar carga sem aprendizado." ], "a", "Reflexão transforma experiência em aprendizagem e planejamento." ]
          ]),
        module_data("TCC: pergunta, método e comunicação", "Estruture um trabalho técnico com pergunta clara, fontes e evidências.",
          "Um trabalho de conclusão começa por um problema delimitado e uma pergunta que possa ser respondida dentro do tempo, dos recursos e das regras de segurança disponíveis. Objetivo geral descreve o resultado pretendido; objetivos específicos dividem o trabalho em etapas observáveis. A justificativa explica a relevância sem prometer resultados antes da investigação.\n\nA revisão de literatura reúne e compara fontes confiáveis, distinguindo o que já se sabe de hipóteses ainda não testadas. O método deve explicar materiais, critérios de amostragem, variáveis, procedimentos, controles e forma de analisar dados de modo que outra pessoa compreenda o caminho seguido. Registre resultados reais, inclusive resultados inesperados, e reconheça limitações.\n\nNa comunicação, apresente pergunta, método, resultados, discussão e conclusão de forma coerente. Cite fontes conforme as normas da instituição, não copie textos e identifique claramente dados próprios e de terceiros. Segurança, ética, privacidade e descarte precisam estar integrados ao planejamento. Consulte orientador e manual acadêmico para requisitos formais.",
          "Pergunta ampla: «A água está contaminada?». Pergunta delimitada: «Qual é a concentração de nitrato em amostras coletadas em três pontos do córrego durante o mês definido, pelo método validado disponível?». A segunda identifica analito, local, período e estratégia de medida.",
          "Qual característica torna uma pergunta de TCC mais investigável?", [ "Delimita objeto, contexto e método ou evidência possível.", "Promete confirmar uma opinião.", "Não define o tema.", "Dispensa fontes." ], "a",
          "Uma pergunta delimitada pode ser respondida com recursos, método e dados definidos.",
          [
            [ "Objetivos específicos devem:", [ "Descrever etapas concretas que contribuem para o objetivo geral.", "Substituir a pergunta de pesquisa.", "Antecipar resultados garantidos.", "Ser impossíveis de observar." ], "a", "Objetivos específicos tornam o plano executável e avaliável." ],
            [ "Uma metodologia deve permitir ao leitor entender:", [ "Como dados foram obtidos e analisados.", "Apenas a opinião do autor.", "Somente o título.", "Resultados que não foram medidos." ], "a", "Método descreve procedimentos e critérios de forma transparente." ],
            [ "Por que citar fontes?", [ "Reconhecer autoria e permitir rastrear informações.", "Aumentar páginas sem propósito.", "Substituir análise própria.", "Ocultar a origem dos dados." ], "a", "Citações dão crédito e permitem verificar a base teórica." ],
            [ "Um resultado inesperado deve ser:", [ "Registrado e discutido à luz dos dados e limitações.", "Apagado automaticamente.", "Substituído por valor esperado.", "Omitido sempre." ], "a", "Resultados devem ser apresentados honestamente e interpretados com cautela." ],
            [ "Uma hipótese de pesquisa é:", [ "Uma explicação ou previsão testável.", "Uma certeza que não pode ser verificada.", "Uma citação.", "Uma norma de segurança." ], "a", "Hipóteses podem ser confrontadas com evidências." ],
