            [ "A conclusão deve ser coerente com:", [ "A pergunta, objetivos e evidências obtidas.", "Expectativas pessoais.", "Dados não coletados.", "Um tema diferente." ], "a", "Conclusões respondem ao que foi investigado com base nas evidências." ],
