            [ "Por que identificar partes interessadas?", [ "Para entender necessidades, impactos e comunicação necessária.", "Para evitar objetivos.", "Para substituir os dados.", "Para eliminar planejamento." ], "a", "Partes interessadas podem afetar ou ser afetadas pelo projeto." ],
