            [ "Uma conclusão válida deve:", [ "Ser sustentada pelos dados e reconhecer limitações.", "Extrapolar para qualquer situação.", "Ignorar os resultados.", "Repetir o objetivo sem análise." ], "a", "As conclusões precisam corresponder ao alcance da evidência." ],
            [ "Em um gráfico técnico, eixos devem indicar:", [ "Variáveis e unidades.", "Somente cores.", "Opiniões.", "Identidade do autor apenas." ], "a", "Rótulos com unidades permitem interpretar medidas." ],
            [ "Um resultado que não confirma a hipótese:", [ "Continua sendo um resultado que deve ser registrado e discutido.", "Deve ser apagado.", "Prova automaticamente fraude.", "Deve ser substituído." ], "a", "Resultados negativos ajudam a revisar hipóteses e métodos." ],
            [ "A validação de uma solução verifica:", [ "Se atende aos critérios de uso definidos.", "Se o projeto tem nome curto.", "Somente se o custo é zero.", "Se os dados podem ser ocultados." ], "a", "Validação compara desempenho com requisitos e critérios de aceitação." ],
            [ "Se a qualidade do produto se altera durante uma redução de consumo, deve-se:", [ "Avaliar a qualidade junto com o indicador de consumo.", "Declarar sucesso sem verificar.", "Ignorar a especificação.", "Mudar a unidade." ], "a", "A otimização deve preservar os requisitos de qualidade." ],
            [ "A documentação de alterações permite:", [ "Rastrear decisões e compreender resultados.", "Eliminar a autoria.", "Substituir a análise.", "Ocultar dependências." ], "a", "Registros facilitam auditoria, repetição e aprendizado." ],
            [ "A apresentação final deve incluir:", [ "Problema, método, evidências, conclusão e próximos passos.", "Somente imagens sem contexto.", "Dados sem unidades.", "Conclusão sem resultados." ], "a", "Uma estrutura lógica ajuda o público a avaliar o projeto." ],
            [ "Uma solução industrialmente viável deve considerar também:", [ "Custo, segurança, manutenção e impactos.", "Somente funcionamento em uma demonstração.", "Apenas aparência.", "Nenhum requisito ambiental." ], "a", "Viabilidade depende de operação confiável e responsável, não só de um teste." ]
