            [ "Por que verificar a data de uma norma ou documento?", [ "Requisitos podem ser revisados e versões antigas podem não valer.", "A data determina a cor do documento.", "Para alterar os resultados.", "Porque fontes recentes são sempre corretas." ], "a", "Atualidade importa, mas deve ser avaliada junto com autoridade e conteúdo." ],
