            [ "Interdisciplinaridade significa:", [ "Relacionar contribuições de diferentes áreas para compreender um problema.", "Misturar assuntos sem conexão.", "Evitar métodos.", "Repetir uma disciplina." ], "a", "Integração mostra como perspectivas diferentes contribuem para a mesma questão." ],
            [ "Ao usar uma ideia de outra pessoa, deve-se:", [ "Citar a fonte conforme as normas aplicáveis.", "Omitir a autoria.", "Apresentar como própria.", "Alterar poucas palavras para dispensar citação." ], "a", "Atribuição reconhece autoria e respeita direitos autorais." ],
            [ "Qual é a diferença entre dado e interpretação?", [ "Dado é observação/medida; interpretação explica seu significado.", "Não há diferença.", "Interpretação é sempre medida direta.", "Dado é opinião." ], "a", "Separar observação de explicação evita confundir evidência com conclusão." ],
            [ "Uma apresentação eficaz deve:", [ "Organizar mensagem conforme a pergunta e o público.", "Exibir todos os detalhes sem hierarquia.", "Evitar conclusão.", "Usar texto ilegível." ], "a", "Estrutura e adequação ao público facilitam entendimento." ],
            [ "Um conflito de interesse em uma fonte:", [ "Deve ser considerado ao avaliar a informação.", "Prova automaticamente que tudo é falso.", "Não precisa ser registrado.", "Substitui análise metodológica." ], "a", "Interesses podem influenciar comunicação e devem ser avaliados junto a evidências." ],
            [ "Uma conclusão de seminário deve:", [ "Responder à pergunta e indicar limites ou incertezas.", "Ir além dos dados sem ressalvas.", "Introduzir tema sem relação.", "Repetir o título." ], "a", "Conclusões claras sintetizam a resposta e o alcance do que foi apresentado." ]
          ]),
        module_data("Comunicação científica e apresentação oral", "Organize a apresentação, explique dados e responda perguntas com transparência.",
          "Uma apresentação técnica eficaz orienta o público por uma sequência clara: problema, importância, objetivos, método, resultados, interpretação e conclusão. Cada slide deve apoiar uma mensagem, não substituir a fala com parágrafos longos. Termos técnicos precisam ser definidos quando o público pode não conhecê-los.\n\nGráficos devem apresentar título informativo, variáveis nos eixos, unidades, legenda e escala legível. Mostre incerteza quando relevante e não distorça escalas para exagerar diferenças. Tabelas são úteis para valores exatos; gráficos destacam padrões. Aponte limitações e diferencie associação de causalidade.\n\nEnsaiar permite ajustar tempo, transições e clareza. Ao responder perguntas, escute até o fim, reconheça quando não sabe e explique como verificaria a resposta. Cite imagens e fontes. A comunicação científica não exige certeza absoluta: exige honestidade sobre evidências, raciocínio e incerteza.",
          "Se um gráfico compara pH de três amostras, identifique cada amostra, coloque pH no eixo com escala adequada e informe como as medidas foram obtidas. Na fala, explique o padrão e evite concluir causa sem um desenho experimental que a sustente.",
          "Qual informação não pode faltar em um gráfico quantitativo?", [ "Unidades e identificação das variáveis nos eixos.", "Apenas cores decorativas.", "Uma conclusão sem dados.", "Um fundo com imagens." ], "a",
          "Rótulos e unidades são necessários para interpretar o que os valores representam.",
