            [ "Uma escala de gráfico truncada pode:", [ "Exagerar visualmente diferenças.", "Alterar os dados medidos.", "Substituir unidade.", "Eliminar incerteza." ], "a", "Escalas precisam ser escolhidas para não induzir interpretação enganosa." ],
            [ "Se não souber responder a uma pergunta do público, é adequado:", [ "Reconhecer o limite e indicar como verificaria.", "Inventar um número.", "Desqualificar a pergunta.", "Mudar de assunto sem reconhecer." ], "a", "Transparência fortalece a credibilidade e abre caminho para investigação." ],
            [ "Uma apresentação deve citar:", [ "Fontes e créditos de materiais utilizados.", "Somente o apresentador.", "Nenhuma fonte visual.", "Dados de terceiros como próprios." ], "a", "Citações reconhecem autoria e permitem rastrear as informações." ],
            [ "Qual formato costuma facilitar a comparação de tendências?", [ "Gráfico com eixos e unidades bem identificados.", "Parágrafo longo em letra pequena.", "Imagem sem legenda.", "Lista de referências apenas." ], "a", "Gráficos podem comunicar padrões quando são construídos e rotulados corretamente." ],
            [ "Incerteza em uma medição deve ser:", [ "Comunicada quando relevante para interpretar o resultado.", "Ocultada sempre.", "Substituída por casas decimais extras.", "Confundida com erro intencional." ], "a", "Incerteza descreve a faixa de valores compatíveis com a medição e método." ],
            [ "Associação entre duas variáveis prova causalidade?", [ "Sim, sempre.", "Não; é necessária evidência e desenho que sustentem causa.", "Sim, se o gráfico for colorido.", "Não existe associação." ], "b", "Correlação não estabelece por si só mecanismo causal." ],
            [ "Ensaiar a apresentação permite:", [ "Verificar tempo, clareza e transições.", "Alterar os resultados.", "Evitar citar fontes.", "Garantir que ninguém fará perguntas." ], "a", "O ensaio ajuda a ajustar conteúdo e comunicação ao tempo disponível." ],
            [ "Uma conclusão oral deve ser:", [ "Consistente com resultados e objetivos.", "Mais ampla que qualquer evidência.", "Uma nova hipótese sem identificação.", "Uma lista de agradecimentos apenas." ], "a", "A conclusão responde aos objetivos sem exceder o que os dados permitem." ]
          ])
